INSERT INTO `site_settings` (`id`, `admin_id`, `created_at`, `updated_at`, `site_name`, `site_url`, `meta_title`, `meta_description`, `copyright_text`, `email_logo`, `header_logo`, `footer_logo`, `primary_color`, `primary_hover_color`, `styling`, `meta_keywords`) VALUES (1,1,'2024-11-19 05:44:41','2026-03-24 05:50:59','FixMyPC Store – Reliable Electronics, Unbeatable Value','https://shop.fixmypc.ie','Your one-stop shop for phones, laptops, tablets, and accessories. Quality, value, and support you can trust!','Discover FixMyPC\'s wide range of new and refurbished mobile phones, tablets, laptops, gaming PCs, business PCs, and accessories. Shop locally stocked items with great prices, fast shipping, and reliable customer support.','All rights reserved by Ishop','email_logo-1774331453-7.png','header_logo-1774331444-9.png','footer_logo-1774331448-7.png','#33319a',NULL,NULL,'Discover,FixMyPC\'s,wide,range,new,refurbished,mobile,phones,tablets,laptops,gaming,PCs,business,PCs,accessories.,Shop,locally,stocked,items,great,prices,fast,shipping,reliable,customer,support.');
INSERT INTO `site_setting_langs` (`id`, `created_at`, `updated_at`, `site_name`, `meta_title`, `meta_description`, `copyright_text`, `lang`, `site_setting_id`, `meta_keywords`) VALUES (1,'2024-11-19 05:44:42','2024-11-21 17:35:15','Ishop','Erkekler, Elektronik, Giyim, Bilgisayar, Kitap, DVD ve daha fazlası için Online Alışveriş','ABD\'nin bebek ve çocuk temel malzemeleri, oyuncakları, moda ve elektronik ürünleri ve daha fazlası için 1 numaralı alışveriş platformu! En Düşük Fiyat Garantisi | Geri Ödeme Fırsatları','Tüm hakları saklıdır Ishop','tr',1,'ABD\'nin,bebek,ve,çocuk,temel,malzemeleri,oyuncakları,moda,ve,elektronik,ürünleri,ve,daha,fazlası,için,numaralı,alışveriş,platformu!,En,Düşük,Fiyat,Garantisi,|,Geri,Ödeme,Fırsatları');
INSERT INTO `site_setting_langs` (`id`, `created_at`, `updated_at`, `site_name`, `meta_title`, `meta_description`, `copyright_text`, `lang`, `site_setting_id`, `meta_keywords`) VALUES (2,'2024-11-19 05:44:42','2024-11-21 17:35:15','Ishop','Achats en ligne pour hommes, électronique, vêtements, ordinateurs, livres, DVD et plus','La plate-forme d\'achat n°1 aux États-Unis pour les articles essentiels pour bébés et enfants, les jouets, la mode et les articles électroniques, et plus encore! Prix le plus bas garanti | Offres de remboursement','Tous droits réservés par Ishop','fr',1,'La,plate-forme,d\'achat,n°1,aux,États-Unis,pour,les,articles,essentiels,pour,bébés,et,enfants,les,jouets,la,mode,et,les,articles,électroniques,et,plus,encore!,Prix,le,plus,bas,garanti,|,Offres,de,remboursement');
INSERT INTO `site_setting_langs` (`id`, `created_at`, `updated_at`, `site_name`, `meta_title`, `meta_description`, `copyright_text`, `lang`, `site_setting_id`, `meta_keywords`) VALUES (3,'2024-11-19 05:44:42','2024-11-21 17:35:15','Ishop','التسوق عبر الإنترنت للرجال والإلكترونيات والملابس وأجهزة الكمبيوتر والكتب وأقراص DVD والمزيد','منصة التسوق رقم 1 في الولايات المتحدة الأمريكية لمستلزمات الأطفال والرضع والألعاب والأزياء والأدوات الإلكترونية والمزيد! أقل سعر مضمون | صفقات استرداد النقود','Ishop جميع الحقوق محفوظة','ar',1,'منصة,التسوق,رقم,في,الولايات,المتحدة,الأمريكية,لمستلزمات,الأطفال,والرضع,والألعاب,والأزياء,والأدوات,الإلكترونية,والمزيد!,أقل,سعر,مضمون,|,صفقات,استرداد,النقود');
INSERT INTO `site_setting_langs` (`id`, `created_at`, `updated_at`, `site_name`, `meta_title`, `meta_description`, `copyright_text`, `lang`, `site_setting_id`, `meta_keywords`) VALUES (4,'2024-11-19 05:44:42','2024-11-21 17:35:15','Ishop','पुरुषों, इलेक्ट्रॉनिक्स, परिधान, कंप्यूटर, किताबें, डीवीडी और बहुत कुछ के लिए ऑनलाइन खरीदारी','बच्चे और बच्चों के आवश्यक सामान, खिलौने, फैशन और इलेक्ट्रॉनिक आइटम, और बहुत कुछ के लिए यूएसए का #1 शॉपिंग प्लेटफॉर्म! सबसे कम कीमत की गारंटी | कैशबैक सौदे','द्वारा सर्वाधिकार सुरक्षित Ishop','hi',1,'बच्चे,और,बच्चों,के,आवश्यक,सामान,खिलौने,फैशन,और,इलेक्ट्रॉनिक,आइटम,और,बहुत,कुछ,के,लिए,यूएसए,का,#1,शॉपिंग,प्लेटफॉर्म!,सबसे,कम,कीमत,की,गारंटी,|,कैशबैक,सौदे');
