INSERT INTO `pages` (`id`, `slug`, `title`, `description`, `meta_title`, `meta_description`, `page_from_component`, `created_at`, `updated_at`, `admin_id`, `meta_keywords`) VALUES (1,'about','About','<h1 style=\"margin: 30px 0;\">About us</h1>\r\n<h2 style=\"margin: 30px 0;\">Definitions</h2>\r\n<p><strong>Account</strong> means a unique account created for You to access our Service orparts of our Service.</p>\r\n<p><strong>Company</strong> (referred to as either &quot;the Company&quot;, &quot;We&quot;,&quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to ishop.cholobangla.com, Canada.<</p>\r\n<p><strong>Cookies</strong> are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.</p>\r\n<p><strong>Country</strong> refers to: New Brunswick, Canada</p>\r\n<p><strong>Device</strong> means any device that can access the Service such as a computer, a cellphone or a digital tablet.</p>\r\n<p><strong>Personal Data</strong> is any information that relates to an identified oridentifiable individual.</p>\r\n<p><strong>Service</strong> refers to the Website.</p>\r\n<p><strong>Service Provider</strong> means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by theCompany to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how theService is used.</p>\r\n<p><strong>Usage Data</strong> refers to data collected automatically, either generated by theuse of the Service or from the Service infrastructure itself (for example, the duration of apage visit).</p>\r\n<p><strong>Website</strong> refers to https://www.ishop.cholobangla.com/, accessible from <a href=\"ishop.com\" rel=\"external nofollow noopener\" target=\"_blank\">ishop.cholobangla.com</a></p>\r\n<p><strong>You</strong> means the individual accessing or using the Service, or the company, orother legal entity on behalf of which such individual is accessing or using the Service, asapplicable.</p>\r\n','Ishop - About','About',2,'2024-11-19 05:44:40','2024-11-21 17:35:15',1,'');
INSERT INTO `pages` (`id`, `slug`, `title`, `description`, `meta_title`, `meta_description`, `page_from_component`, `created_at`, `updated_at`, `admin_id`, `meta_keywords`) VALUES (2,'faq','Faq','<h1 style=\"margin: 30px 0;\">Frequently asked questions</h1>\r\n<h2 style=\"margin: 30px 0;\">Overview?</h2>\r\n<p>ishop is a multi vendor ecommerce CMS.API is build with <b>laravel</b>, admin panel and the front end is build with<strong>nuxt js</strong>.For storing data <b>mysql</b> is being used. The performance of the site is super fast because of advance <b>caching</b> system. It is fully responsive and highly customizable. In the regular licence admin panel build files will not be found, that\'s mean you won\'t be able to customize any design of the admin panel. Frontend and API source code will be found in the package folder. You can customize the frontend and API as your requirements very easily. Admin panel source code will be found in the extended licence. For any query, please contact our team for support at <a href=\"mailto:iyozedcontact@gmail.com\" class=\"link\"><b>iyozedcontact@gmail.com</b></a></p>\r\n<h2 style=\"margin: 30px 0;\">Do we provide installation support to the users?</h2>\r\n<p>Yes, we provide installation support to the users. Feel free to email us anytime.</p>\r\n<h2 style=\"margin: 30px 0;\">Do we provide installation guide to the users?</h2>\r\n<p>Yes, we provide installation guide to the users with the packages.</p>\r\n<h2 style=\"margin: 30px 0;\">How much time do we take to get back to the user?</h2>\r\n<p>We reply to the users as soon as possible.</p>\r\n\r\n','Ishop - Faq','Faq',2,'2024-11-19 05:44:40','2024-11-21 17:35:15',1,'Faq');
INSERT INTO `pages` (`id`, `slug`, `title`, `description`, `meta_title`, `meta_description`, `page_from_component`, `created_at`, `updated_at`, `admin_id`, `meta_keywords`) VALUES (3,'contact','Contact','Contact','Ishop - Contact','Contact',1,'2024-11-19 05:44:40','2024-11-21 17:35:15',1,'Contact');
INSERT INTO `pages` (`id`, `slug`, `title`, `description`, `meta_title`, `meta_description`, `page_from_component`, `created_at`, `updated_at`, `admin_id`, `meta_keywords`) VALUES (4,'refund-policy','Refund Policy','<h1 style=\"margin: 30px 0;\">Refund Policy</h1>\r\n<h2 style=\"margin: 30px 0;\">Definitions</h2>\r\n<p>For the purposes of this Privacy Policy:</p>\r\n<p><strong>Account</strong> means a unique account created for You to access our Service or parts of our Service.</p>\r\n<p><strong>Company</strong> (referred to as either &quot;the Company&quot;, &quot;We&quot;,&quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to ishop.cholobangla.com, Canada.</p>\r\n<p><strong>Cookies</strong> are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.</p>\r\n<p><strong>Country</strong> refers to: New Brunswick, Canada</p>\r\n<p><strong>Device</strong> means any device that can access the Service such as a computer, a cellphone or a digital tablet.</p>\r\n<p><strong>Personal Data</strong> is any information that relates to an identified or identifiable individual.</p>\r\n<p><strong>Service</strong> refers to the Website.</p>\r\n<p><strong>Service Provider</strong> means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how the Service is used.</p>\r\n<p><strong>Usage Data</strong> refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit).</p>\r\n<p><strong>Website</strong> refers to https://ishop.cholobangla.com/, accessible from <a href=\"ishop.cholobangla.com\" rel=\"external nofollow noopener\" target=\"_blank\">ishop.cholobangla.com</a></p>\r\n<p><strong>You</strong> means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable.</p>\r\n<h1 style=\"margin: 30px 0;\">Collecting and Using Your Personal Data</h1>\r\n<h2 style=\"margin: 30px 0;\">Types of Data Collected</h2>\r\n<h3 style=\"margin: 30px 0;\">Personal Data</h3>\r\n<p>While using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:</p>\r\n<ul style=\"margin: 30px 0;\"><li>Email address</li><li>First name and last name</li><li>Address, State, Province, ZIP/Postal code, City</li><li>Usage Data</li></ul>\r\n<h3 style=\"margin: 30px 0;\">Usage Data</h3>\r\n<p>Usage Data is collected automatically when using the Service.</p>\r\n<p>Usage Data may include information such as Your Device\'s Internet Protocol address (e.g. IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers and other diagnostic data.</p>\r\n<p>When You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.</p>\r\n<p>We may also collect information that Your browser sends whenever You visit our Service or when You access the Service by or through a mobile device.</p>\r\n<h3 style=\"margin: 30px 0;\">Tracking Technologies and Cookies</h3>\r\n<p>We use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies used are beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The technologies We use may include:</p>\r\n<ul style=\"margin: 30px 0;\"><li><strong>Cookies or Browser Cookies.</strong> A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it will refuse Cookies, our Service may use Cookies.</li><li><strong>Web Beacons.</strong> Certain sections of our Service and our emails may contain small electronic files known as web beacons (also referred to as clear gifs, pixel tags, and single-pixel gifs) that permit the Company, for example, to count users who have visited those pages or opened an email and for other related website statistics (for example, recording the popularity of a certain section and verifying system and server integrity).</li></ul>\r\n<p>Cookies can be &quot;Persistent&quot; or &quot;Session&quot; Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. Learn more about cookies on the <a href=\"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\">Free Privacy Policy website</a> article.</p>\r\n<p>We use both Session and Persistent Cookies for the purposes set out below:</p>\r\n<p><strong>Necessary / Essential Cookies</strong></p>\r\n<p>Type: Session Cookies</p>\r\n<p>Administered by: Us</p>\r\n<p>Purpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services.</p>\r\n<p><strong>Cookies Policy / Notice Acceptance Cookies</strong></p>\r\n<p>Type: Persistent Cookies</p>\r\n<p>Administered by: Us</p>\r\n<p>Purpose: These Cookies identify if users have accepted the use of cookies on the Website.</p>\r\n<p><strong>Functionality Cookies</strong></p>\r\n<p>Type: Persistent Cookies</p>\r\n<p>Administered by: Us</p>\r\n<p>Purpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website.</p>\r\n<p>For more information about the cookies we use and your choices regarding cookies, please visit our Cookies Policy or the Cookies section of our Privacy Policy.</p>\r\n<h2 style=\"margin: 30px 0;\">Use of Your Personal Data</h2>\r\n<p>The Company may use Personal Data for the following purposes:</p>\r\n<p><strong>To provide and maintain our Service</strong>, including to monitor the usage of our Service.</p>\r\n<p><strong>To manage Your Account:</strong> to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities of the Service that are available to You as a registered user.</p>\r\n<p><strong>For the performance of a contract:</strong> the development, compliance and undertaking of the purchase contract for the products, items or services You have purchased or of any other contract with Us through the Service.</p>\r\n<p><strong>To contact You:</strong> To contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication, such as a mobile application\'s push notifications regarding updates or informative communications related to the functionalities, products or contracted services, including the security updates, when necessary or reasonable for their implementation.</p>\r\n<p><strong>To provide You</strong> with news, special offers and general information about other goods, services and events which we offer that are similar to those that you have already purchased or enquired about unless You have opted not to receive such information.</p>\r\n<p><strong>To manage Your requests:</strong> To attend and manage Your requests to Us.</p>\r\n<p><strong>For business transfers:</strong> We may use Your information to evaluate or conduct a merger, divestiture, restructuring, reorganization, dissolution, or other sale or transfer of some or all of Our assets, whether as a going concern or as part of bankruptcy, liquidation, or similar proceeding, in which Personal Data held by Us about our Service users is among the assets transferred.</p>\r\n<p><strong>For other purposes</strong>: We may use Your information for other purposes, such as data analysis, identifying usage trends, determining the effectiveness of our promotional campaigns and to evaluate and improve our Service, products, services, marketing and your experience.</p>\r\n','Ishop - Refund Policy','Refund Policy',2,'2024-11-19 05:44:40','2024-11-21 17:35:15',1,'Refund,Policy');
INSERT INTO `pages` (`id`, `slug`, `title`, `description`, `meta_title`, `meta_description`, `page_from_component`, `created_at`, `updated_at`, `admin_id`, `meta_keywords`) VALUES (5,'privacy-policy','Privacy Policy','<h1 style=\"margin: 30px 0;\">Privacy Policy</h1>\r\n<p>Last updated: December 13, 2022</p>\r\n<p>This Privacy Policy describes Our policies and procedures on the collection, use and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You.</p>\r\n<p>We use Your Personal data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy. This Privacy Policy has been created with the help of the <a href=\"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\" target=\"_blank\">Free Privacy Policy Generator</a>.</p>\r\n<h1 style=\"margin: 30px 0;\">Interpretation and Definitions</h1>\r\n<h2 style=\"margin: 30px 0;\">Interpretation</h2>\r\n<p>The words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural.</p>\r\n<h2 style=\"margin: 30px 0;\">Definitions</h2>\r\n<p>For the purposes of this Privacy Policy:</p>\r\n<strong>Account</strong> means a unique account created for You to access our Service or parts of our Service.</p>\r\n<p><strong>Company</strong> (referred to as either &quot;the Company&quot;, &quot;We&quot;,&quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to ishop.cholobangla.com, Canada.</p>\r\n<p><strong>Cookies</strong> are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.</p>\r\n<p><strong>Country</strong> refers to: New Brunswick, Canada</p>\r\n<p><strong>Device</strong> means any device that can access the Service such as a computer, a cellphone or a digital tablet.</p>\r\n<p><strong>Personal Data</strong> is any information that relates to an identified or identifiable individual.</p>\r\n<p><strong>Service</strong> refers to the Website.</p>\r\n<p><strong>Service Provider</strong> means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how the Service is used.</p>\r\n<p><strong>Usage Data</strong> refers to data collected automatically, either generated by the use of the Service or from the Service infrastructure itself (for example, the duration of a page visit).</p>\r\n<p><strong>Website</strong> refers to https://ishop.cholobangla.com/, accessible from <a href=\"ishop.cholobangla.com\" rel=\"external nofollow noopener\" target=\"_blank\">ishop.cholobangla.com</a></p>\r\n<p><strong>You</strong> means the individual accessing or using the Service, or the company, or other legal entity on behalf of which such individual is accessing or using the Service, as applicable.</p>\r\n<h1 style=\"margin: 30px 0;\">Collecting and Using Your Personal Data</h1>\r\n<h2 style=\"margin: 30px 0;\">Types of Data Collected</h2>\r\n<h3 style=\"margin: 30px 0;\">Personal Data</h3>\r\n<p>While using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:</p>\r\n<ul style=\"margin: 30px 0;\"><li>Email address</li><li>First name and last name</li><li>Address, State, Province, ZIP/Postal code, City</li><li>Usage Data</li></ul>\r\n<h3 style=\"margin: 30px 0;\">Usage Data</h3>\r\n<p>Usage Data is collected automatically when using the Service.</p>\r\n<p>Usage Data may include information such as Your Device\'s Internet Protocol address (e.g. IP address), browser type, browser version, the pages of our Service that You visit, the time and date of Your visit, the time spent on those pages, unique device identifiers and other diagnostic data.</p>\r\n<p>When You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.</p>\r\n<p>We may also collect information that Your browser sends whenever You visit our Service or when You access the Service by or through a mobile device.</p>\r\n<h3 style=\"margin: 30px 0;\">Tracking Technologies and Cookies</h3>\r\n<p>We use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies used are beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The technologies We use may include:</p>\r\n<p><strong>Cookies or Browser Cookies.</strong> A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it will refuse Cookies, our Service may use Cookies.</p>\r\n<p><strong>Web Beacons.</strong> Certain sections of our Service and our emails may contain small electronic files knownas web beacons (also referred to as clear gifs, pixel tags, andsingle-pixel gifs) that permit the Company, for example, to count users who have visited thosepages or opened an email and for other related website statistics (for example, recording thepopularity of a certain section and verifying system and server integrity).</p>\r\n<p>Cookies can be &quot;Persistent&quot; or &quot;Session&quot; Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. Learn more about cookies on the <a href=\"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\">Free Privacy Policy website</a> article.</p>\r\n<p>We use both Session and Persistent Cookies for the purposes set out below:</p>\r\n<p><strong>Necessary / Essential Cookies</strong></p>\r\n<p>Type: Session Cookies</p>\r\n<p>Administered by: Us</p>\r\n<p>Purpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users and prevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services.</p>\r\n<p><strong>Cookies Policy / Notice Acceptance Cookies</strong></p>\r\n<p>Type: Persistent Cookies</p>\r\n<p>Administered by: Us</p>\r\n<p>Purpose: These Cookies identify if users have accepted the use of cookies on the Website.</p>\r\n<p><strong>Functionality Cookies</strong></p>\r\n<p>Type: Persistent Cookies</p>\r\n<p>Administered by: Us</p>\r\n<p>Purpose: These Cookies allow us to remember choices You make when You use the Website, such as remembering your login details or language preference. The purpose of these Cookies is to provide You with a more personal experience and to avoid You having to re-enter your preferences every time You use the Website.</p>\r\n<p>For more information about the cookies we use and your choices regarding cookies, please visit our Cookies Policy or the Cookies section of our Privacy Policy.</p>\r\n<h2 style=\"margin: 30px 0;\">Use of Your Personal Data</h2>\r\n<p>The Company may use Personal Data for the following purposes:</p>\r\n<p><strong>To provide and maintain our Service</strong>, including to monitor the usage of our Service.</p>\r\n<p><strong>To manage Your Account:</strong> to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities of the Service that are available to You as a registered user.</p>\r\n<p><strong>For the performance of a contract:</strong> the development, compliance and undertaking of the purchase contract for the products, items or services You have purchased or of any other contract with Us through the Service.</p>\r\n<p><strong>To contact You:</strong> To contact You by email, telephone calls, SMS, or other equivalent forms of electronic communication, such as a mobile application\'s push notifications regarding updates or informative communications related to the functionalities, products or contracted services, including the security updates, when necessary or reasonable for their implementation.</p>\r\n<p><strong>To provide You</strong> with news, special offers and general information about other goods, services and events which we offer that are similar to those that you have already purchased or enquired about unless You have opted not to receive such information.</p>\r\n<p><strong>To manage Your requests:</strong> To attend and manage Your requests to Us.</p>\r\n<p><strong>For business transfers:</strong> We may use Your information to evaluate or conduct a merger, divestiture, restructuring, reorganization, dissolution, or other sale or transfer of some or all of Our assets, whether as a going concern or as part of bankruptcy, liquidation, or similar proceeding, in which Personal Data held by Us about our Service users is among the assets transferred.</p>\r\n<p><strong>For other purposes</strong>: We may use Your information for other purposes, such as data analysis, identifying usage trends, determining the effectiveness of our promotional campaigns and to evaluate and improve our Service, products, services, marketing and your experience.</p>\r\n<p>We may share Your personal information in the following situations:</p>\r\n<ul style=\"margin: 30px 0;\"><li><strong>With Service Providers:</strong> We may share Your personal information with Service Providers to monitor and analyze the use of our Service, to contact You.</li><li><strong>For business transfers:</strong> We may share or transfer Your personal information in connection with, or during negotiations of, any merger, sale of Company assets, financing, or acquisition of all or a portion of Our business to another company.</li><li><strong>With Affiliates:</strong> We may share Your information with Our affiliates, in which case we will require those affiliates to honor this Privacy Policy. Affiliates include Our parent company and any other subsidiaries, joint venture partners or other companies that We control or that are under common control with Us.</li><li><strong>With business partners:</strong> We may share Your information with Our business partners to offer You certain products, services or promotions.</li><li><strong>With other users:</strong> when You share personal information or otherwise interact in the public areas with other users, such information may be viewed by all users and may be publicly distributed outside.</li><li><strong>With Your consent</strong>: We may disclose Your personal information for any other purpose with Your consent.</li></ul>\r\n<h2 style=\"margin: 30px 0;\">Retention of Your Personal Data</h2>\r\n<p>The Company will retain Your Personal Data only for as long as is necessary for the purposes set out in this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply with our legal obligations (for example, if we are required to retain your data to comply with applicable laws), resolve disputes, and enforce our legal agreements and policies.</p>\r\n<p>The Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer time periods.</p>\r\n<h2 style=\"margin: 30px 0;\">Transfer of Your Personal Data</h2>\r\n<p>Your information, including Personal Data, is processed at the Company\'s operating offices and in any other places where the parties involved in the processing are located. It means that this information may be transferred to — and maintained on — computers located outside of Your state, province, country or other governmental jurisdiction where the data protection laws may differ than those from Your jurisdiction.</p>\r\n<p>Your consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer.</p>\r\n<p>The Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place including the security of Your data and other personal information.</p>\r\n<h2 style=\"margin: 30px 0;\">Delete Your Personal Data</h2>\r\n<p>You have the right to delete or request that We assist in deleting the Personal Data that We have collected about You.</p>\r\n<p>Our Service may give You the ability to delete certain information about You from within the Service.</p>\r\n<p>You may update, amend, or delete Your information at any time by signing in to Your Account, if you have one, and visiting the account settings section that allows you to manage Your personal information. You may also contact Us to request access to, correct, or delete any personal information that You have provided to Us.</p>\r\n<p>Please note, however, that We may need to retain certain information when we have a legal obligation or lawful basis to do so.</p>\r\n<h2 style=\"margin: 30px 0;\">Disclosure of Your Personal Data</h2>\r\n<h3 style=\"margin: 30px 0;\">Business Transactions</h3>\r\n<p>If the Company is involved in a merger, acquisition or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy.</p>\r\n<h3 style=\"margin: 30px 0;\">Law enforcement</h3>\r\n<p>Under certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g. a court or a government agency).</p>\r\n<h3 style=\"margin: 30px 0;\">Other legal requirements</h3>\r\n<p>The Company may disclose Your Personal Data in the good faith belief that such action is necessary to:</p>\r\n<ul><li>Comply with a legal obligation</li><li>Protect and defend the rights or property of the Company</li><li>Prevent or investigate possible wrongdoing in connection with the Service</li><li>Protect the personal safety of Users of the Service or the public</li><li>Protect against legal liability</li></ul>\r\n<h2>Security of Your Personal Data</h2>\r\n<p>The security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage is 100% secure. While We strive to use commercially acceptable means to protect Your Personal Data, We cannot guarantee its absolute security.</p>\r\n<h1>Children\'s Privacy</h1>\r\n<p>Our Service does not address anyone under the age of 13. We do not knowingly collect personally identifiable information from anyone under the age of 13. If You are a parent or guardian and You are aware that Your child has provided Us with Personal Data, please contact Us. If We become aware that We have collected Personal Data from anyone under the age of 13 without verification of parental consent, We take steps to remove that information from Our servers.</p>\r\n<p>If We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent\'s consent before We collect and use that information.</p>\r\n<h1 style=\"margin: 30px 0;\">Links to Other Websites</h1>\r\n<p>Our Service may contain links to other websites that are not operated by Us. If You click on a third party link, You will be directed to that third party\'s site. We strongly advise You to review the Privacy Policy of every site You visit.</p>\r\n<p>We have no control over and assume no responsibility for the content, privacy policies or practices of any third party sites or services.</p>\r\n<h1 style=\"margin: 30px 0;\">Changes to this Privacy Policy</h1>\r\n<p>We may update Our Privacy Policy from time to time. We will notify You of any changes by posting the new Privacy Policy on this page.</p>\r\n<p>We will let You know via email and/or a prominent notice on Our Service, prior to the change becoming effective and update the &quot;Last updated&quot; date at the top of this Privacy Policy.</p>\r\n<p>You are advised to review this Privacy Policy periodically for any changes. Changes to this Privacy Policy are effective when they are posted on this page.</p>\r\n<h1 style=\"margin: 30px 0;\">Contact Us</h1>\r\n<p>If you have any questions about this Privacy Policy, You can contact us:</p>\r\n<ul style=\"margin: 30px 0;\"><li>By visiting this page on our website: <a href=\"https://ishop.cholobangla.com/\" rel=\"external nofollow noopener\" target=\"_blank\">https://ishop.cholobangla.com/</a></li></ul>','Ishop - Privacy Policy','Privacy Policy',2,'2024-11-19 05:44:40','2024-11-21 17:35:15',1,'Privacy,Policy');
INSERT INTO `pages` (`id`, `slug`, `title`, `description`, `meta_title`, `meta_description`, `page_from_component`, `created_at`, `updated_at`, `admin_id`, `meta_keywords`) VALUES (6,'help','Help','<h1 style=\"margin: 30px 0;\">Help</h1>\r\n<p>This Privacy Policy describes Our policies and procedures on the collection, use and disclosure of Your information when You use the Service and tells You about Your privacy rights and how the law protects You.</p>\r\n<p>We use Your Personal data to provide and improve the Service. By using the Service, You agree to the collection and use of information in accordance with this Privacy Policy. This Privacy Policy has been created with the help of the <a href=\"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\" target=\"_blank\">Free Privacy Policy Generator</a>.</p>\r\n<h1 style=\"margin: 30px 0;\">Interpretation and Definitions</h1>\r\n<h2 style=\"margin: 30px 0;\">Interpretation</h2>\r\n<p>The words of which the initial letter is capitalized have meanings defined under the following conditions. The following definitions shall have the same meaning regardless of whether they appear in singular or in plural.</p>\r\n<h2 style=\"margin: 30px 0;\">Definitions</h2>\r\n<p>For the purposes of this Privacy Policy:</p>\r\n<p><strong>Account</strong> means a unique account created for You to access our Service orparts of our Service.</p>\r\n<p><strong>Company</strong> (referred to as either &quot;the Company&quot;, &quot;We&quot;, &quot;Us&quot; or &quot;Our&quot; in this Agreement) refers to ishop.cholobangla.com, Canada.</p>\r\n<p><strong>Cookies</strong> are small files that are placed on Your computer, mobile device or any other device by a website, containing the details of Your browsing history on that website among its many uses.</p>\r\n<p><strong>Country</strong> refers to: New Brunswick, Canada</p>\r\n<p><strong>Device</strong> means any device that can access the Service such as a computer, acellphone or a digital tablet.</p>\r\n<p><strong>Personal Data</strong> is any information that relates to an identified oridentifiable individual.</p>\r\n<p><strong>Service</strong> refers to the Website.</p>\r\n<p><strong>Service Provider</strong> means any natural or legal person who processes the data on behalf of the Company. It refers to third-party companies or individuals employed by the Company to facilitate the Service, to provide the Service on behalf of the Company, to perform services related to the Service or to assist the Company in analyzing how the Service is used.</p>\r\n<p><strong>Usage Data</strong> refers to data collected automatically, either generated by theuse of the Service or from the Service infrastructure itself (for example, the duration of apage visit).</p>\r\n<p><strong>Website</strong> refers to https://ishop.cholobangla.com/, accessible from <a href=\"ishop.cholobangla\" rel=\"external nofollow noopener\" target=\"_blank\">ishop.cholobangla.com</a></p>\r\n<p><strong>You</strong> means the individual accessing or using the Service, or the company, or other leg entity on behalf of which such individual is accessing or using the Service, as applicable.</p>\r\n<h1 style=\"margin: 30px 0;\">Collecting and Using Your Personal Data</h1>\r\n<h2 style=\"margin: 30px 0;\">Types of Data Collected</h2>\r\n<h3 style=\"margin: 30px 0;\">Personal Data</h3>\r\n<p>While using Our Service, We may ask You to provide Us with certain personally identifiable information that can be used to contact or identify You. Personally identifiable information may include, but is not limited to:</p>\r\n<ul style=\"margin: 30px 0;\"><li>Email address</li><li>First name and last name</li><li>Address, State, Province, ZIP/Postal code, City</li><li>Usage Data</li></ul>\r\n<h3 style=\"margin: 30px 0;\">Usage Data</h3>\r\n<p>Usage Data is collected automatically when using the Service.</p><p>Usage Data may include information such as Your Device\'s Internet Protocol address (e.g. IP address),browser type, browser version, the pages of our Service that You visit, the time and date of Yourvisit, the time spent on those pages, unique device identifiers and other diagnostic data.</p><p>When You access the Service by or through a mobile device, We may collect certain information automatically, including, but not limited to, the type of mobile device You use, Your mobile device unique ID, the IP address of Your mobile device, Your mobile operating system, the type of mobile Internet browser You use, unique device identifiers and other diagnostic data.</p>\r\n<p>We may also collect information that Your browser sends whenever You visit our Service or when You access the Service by or through a mobile device.</p>\r\n<h3 style=\"margin: 30px 0;\">Tracking Technologies and Cookies</h3>\r\n<p>We use Cookies and similar tracking technologies to track the activity on Our Service and store certain information. Tracking technologies used are beacons, tags, and scripts to collect and track information and to improve and analyze Our Service. The technologies We use may include:</p>\r\n<p><strong>Cookies or Browser Cookies.</strong> A cookie is a small file placed on Your Device. You can instruct Your browser to refuse all Cookies or to indicate when a Cookie is being sent. However, if You do not accept Cookies, You may not be able to use some parts of our Service. Unless you have adjusted Your browser setting so that it will refuse Cookies, our Service may use Cookies. </p>\r\n<p><strong>Web Beacons.</strong> Certain sections of our Service and our emails may contain small\r\nelectronic files known as web beacons (also referred to as clear gifs, pixel tags, and single-pixel gifs) that permit the Company, for example, to count users who have visited those\r\npages or opened an email and for other related website statistics (for example, recording the popularity of a certain section and verifying system and server integrity).</p>\r\n<p>Cookies can be &quot;Persistent&quot; or &quot;Session&quot; Cookies. Persistent Cookies remain on Your personal computer or mobile device when You go offline, while Session Cookies are deleted as soon as You close Your web browser. Learn more about cookies on the <a href=\"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\">Free Privacy Policy website</a> article.</p>\r\n<p>We use both Session and Persistent Cookies for the purposes set out below:</p>\r\n<p><strong>Necessary / Essential Cookies</strong></p>\r\n<p>Type: Session Cookies</p>\r\n<p>Administered by: Us</p>\r\n<p>Purpose: These Cookies are essential to provide You with services available through the Website and to enable You to use some of its features. They help to authenticate users andprevent fraudulent use of user accounts. Without these Cookies, the services that You have asked for cannot be provided, and We only use these Cookies to provide You with those services.</p>\r\n<p><strong>Cookies Policy / Notice Acceptance Cookies</strong></p>\r\n<p>Type: Persistent Cookies</p><p>Administered by: Us</p><p>Purpose: These Cookies identify if users have accepted the use of cookies on the Website.</p><p><strong>Functionality Cookies</strong></p><p>Type: Persistent Cookies</p><p>Administered by: Us</p><p>Purpose: These Cookies allow us to remember choices You make when You use the Website, suchas remembering your login details or language preference. The purpose of these Cookies is toprovide You with a more personal experience and to avoid You having to re-enter yourpreferences every time You use the Website.</p><p>For more information about the cookies we use and your choices regarding cookies, please visit ourCookies Policy or the Cookies section of our Privacy Policy.</p>\r\n<h2 style=\"margin: 30px 0;\">Use of Your Personal Data</h2><p>The Company may use Personal Data for the following purposes:</p>\r\n<p><strong>To provide and maintain our Service</strong>, including to monitor the usage of ourService.</p>\r\n<p><strong>To manage Your Account:</strong> to manage Your registration as a user of the Service. The Personal Data You provide can give You access to different functionalities ofthe Service that are available to You as a registered user.</p><p><strong>For the performance of a contract:</strong> the development, compliance andundertaking of the purchase contract for the products, items or services You have purchasedor of any other contract with Us through the Service.</p><p><strong>To contact You:</strong> To contact You by email, telephone calls, SMS, or otherequivalent forms of electronic communication, such as a mobile application\'s pushnotifications regarding updates or informative communications related to thefunctionalities, products or contracted services, including the security updates, whennecessary or reasonable for their implementation.</p><p><strong>To provide You</strong> with news, special offers and general information about othergoods, services and events which we offer that are similar to those that you have alreadypurchased or enquired about unless You have opted not to receive such information.</p><p><strong>To manage Your requests:</strong> To attend and manage Your requests to Us.</p><p><strong>For business transfers:</strong> We may use Your information to evaluate or conduct amerger, divestiture, restructuring, reorganization, dissolution, or other sale or transferof some or all of Our assets, whether as a going concern or as part of bankruptcy,liquidation, or similar proceeding, in which Personal Data held by Us about our Serviceusers is among the assets transferred.</p>\r\n<p><strong>For other purposes</strong>: We may use Your information for other purposes, such asdata analysis, identifying usage trends, determining the effectiveness of our promotionalcampaigns and to evaluate and improve our Service, products, services, marketing and yourexperience.</p>\r\n<p>We may share Your personal information in the following situations:</p>\r\n<ul style=\"margin: 30px 0;\"><li><strong>With Service Providers:</strong> We may share Your personal information with ServiceProviders to monitor and analyze the use of our Service, to contact You.</li><li><strong>For business transfers:</strong> We may share or transfer Your personal information inconnection with, or during negotiations of, any merger, sale of Company assets, financing, oracquisition of all or a portion of Our business to another company.</li><li><strong>With Affiliates:</strong> We may share Your information with Our affiliates, in whichcase we will require those affiliates to honor this Privacy Policy. Affiliates include Ourparent company and any other subsidiaries, joint venture partners or other companies that Wecontrol or that are under common control with Us.</li><li><strong>With business partners:</strong> We may share Your information with Our businesspartners to offer You certain products, services or promotions.</li><li><strong>With other users:</strong> when You share personal information or otherwise interact inthe public areas with other users, such information may be viewed by all users and may bepublicly distributed outside.</li><li><strong>With Your consent</strong>: We may disclose Your personal information for any otherpurpose with Your consent.</li></ul>\r\n<h2 style=\"margin: 30px 0;\">Retention of Your Personal Data</h2>\r\n<p>The Company will retain Your Personal Data only for as long as is necessary for the purposes set out\r\nin this Privacy Policy. We will retain and use Your Personal Data to the extent necessary to comply\r\nwith our legal obligations (for example, if we are required to retain your data to comply with\r\napplicable laws), resolve disputes, and enforce our legal agreements and policies.</p>\r\n<p>The Company will also retain Usage Data for internal analysis purposes. Usage Data is generally retained for a shorter period of time, except when this data is used to strengthen the security or to improve the functionality of Our Service, or We are legally obligated to retain this data for longer time periods.</p>\r\n<h2 style=\"margin: 30px 0;\">Transfer of Your Personal Data</h2>\r\n<p>Your information, including Personal Data, is processed at the Company\'s operating offices and in anyother places where the parties involved in the processing are located. It means that this\r\ninformation may be transferred to — and maintained on — computers located outside of Your state, province, country or other governmental jurisdiction where the data protection laws may differ than those from Your jurisdiction.</p>\r\n<p>Your consent to this Privacy Policy followed by Your submission of such information represents Your agreement to that transfer.</p>\r\n<p>The Company will take all steps reasonably necessary to ensure that Your data is treated securely and in accordance with this Privacy Policy and no transfer of Your Personal Data will take place to an organization or a country unless there are adequate controls in place including the security of Your data and other personal information.</p>\r\n<h2 style=\"margin: 30px 0;\">Delete Your Personal Data</h2>\r\n<p>You have the right to delete or request that We assist in deleting the Personal Data that We havecollected about You.</p>\r\n<p>Our Service may give You the ability to delete certain information about You from within theService.</p>\r\n<p>You may update, amend, or delete Your information at any time by signing in to Your Account, if youhave one, and visiting the account settings section that allows you to manage Your personalinformation. You may also contact Us to request access to, correct, or delete any personal information that You have provided to Us.</p>\r\n<p>Please note, however, that We may need to retain certain information when we have a legal obligation or lawful basis to do so.</p>\r\n<h2 style=\"margin: 30px 0;\">Disclosure of Your Personal Data</h2>\r\n<h3 style=\"margin: 30px 0;\">Business Transactions</h3>\r\n<p>If the Company is involved in a merger, acquisition or asset sale, Your Personal Data may be transferred. We will provide notice before Your Personal Data is transferred and becomes subject to a different Privacy Policy.</p>\r\n<h3 style=\"margin: 30px 0;\">Law enforcement</h3>\r\n<p>Under certain circumstances, the Company may be required to disclose Your Personal Data if required to do so by law or in response to valid requests by public authorities (e.g. a court or a government agency).</p>\r\n<h3 style=\"margin: 30px 0;\">Other legal requirements</h3>\r\n<p>The Company may disclose Your Personal Data in the good faith belief that such action is necessary to:</p>\r\n<ul><li>Comply with a legal obligation</li><li>Protect and defend the rights or property of the Company</li><li>Prevent or investigate possible wrongdoing in connection with the Service</li><li>Protect the personal safety of Users of the Service or the public</li><li>Protect against legal liability</li></ul>\r\n<h2>Security of Your Personal Data</h2>\r\n<p>The security of Your Personal Data is important to Us, but remember that no method of transmission over the Internet, or method of electronic storage is 100% secure. While We strive to use commercially acceptable means to protect Your Personal Data, We cannot guarantee its absolute security.</p>\r\n<h1>Children\'s Privacy</h1>\r\n<p>Our Service does not address anyone under the age of 13. We do not knowingly collect personally identifiable information from anyone under the age of 13. If You are a parent or guardian and Youare aware that Your child has provided Us with Personal Data, please contact Us. If We become aware that We have collected Personal Data from anyone under the age of 13 without verification of parental consent, We take steps to remove that information from Our servers.</p>\r\n<p>If We need to rely on consent as a legal basis for processing Your information and Your country requires consent from a parent, We may require Your parent\'s consent before We collect and use that information.</p>\r\n<h1 style=\"margin: 30px 0;\">Links to Other Websites</h1>\r\n<p>Our Service may contain links to other websites that are not operated by Us. If You click on a thirdparty link, You will be directed to that third party\'s site. We strongly advise You to review thePrivacy Policy of every site You visit.</p>\r\n<p>We have no control over and assume no responsibility for the content, privacy policies or practicesof any third party sites or services.</p>\r\n<h1 style=\"margin: 30px 0;\">Changes to this Privacy Policy</h1>\r\n<p>We may update Our Privacy Policy from time to time. We will notify You of any changes by posting thenew Privacy Policy on this page.</p>\r\n<p>We will let You know via email and/or a prominent notice on Our Service, prior to the change becomingeffective and update the &quot;Last updated&quot; date at the top of this Privacy Policy.</p>\r\n<p>You are advised to review this Privacy Policy periodically for any changes. Changes to this PrivacyPolicy are effective when they are posted on this page.</p>\r\n<h1 style=\"margin: 30px 0;\">Contact Us</h1>\r\n<p>If you have any questions about this Privacy Policy, You can contact us:</p>\r\n<ul style=\"margin: 30px 0;\"><li>By visiting this page on our website: <a href=\"https://ishop.cholobangla.com/\" rel=\"external nofollow noopener\" target=\"_blank\">https://ishop.cholobangla.com/</a></li></ul>\r\n<p>Generated using <a href=\"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\"target=\"_blank\">Free Privacy Policy Generator</a></p>\r\n','Ishop - Help','Help',2,'2024-11-19 05:44:40','2024-11-21 17:35:15',1,'Help');
INSERT INTO `pages` (`id`, `slug`, `title`, `description`, `meta_title`, `meta_description`, `page_from_component`, `created_at`, `updated_at`, `admin_id`, `meta_keywords`) VALUES (7,'sitemap','Sitemap','Sitemap','Ishop - Sitemap','Sitemap',1,'2024-11-19 05:44:40','2024-11-21 17:35:15',1,'Sitemap');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (1,'2024-11-19 05:44:41','2024-11-21 17:35:15','عن','<h1 style = \"margin: 30px 0؛\"> عنا </h1>\r\n<h2 style = \"margin: 30px 0؛\"> تعريفات </h2>\r\n<p> <strong> الحساب </strong> يعني حسابًا فريدًا تم إنشاؤه لك للوصول إلى خدمتنا أو أجزاء من خدمتنا. </p>\r\n<p> <strong> الشركة </strong> (يشار إليها باسم & quot؛ الشركة & \"، & quot؛ نحن & quot؛، & quot؛ لنا & quot؛ أو & quot؛ لدينا & quot؛ في هذه الاتفاقية) تشير إلى ishop.cholobangla.com ، كندا. <</p>\r\n<p> <strong> ملفات تعريف الارتباط </strong> هي ملفات صغيرة يتم وضعها على جهاز الكمبيوتر أو الجهاز المحمول أو أي جهاز آخر بواسطة موقع ويب ، وتحتوي على تفاصيل محفوظات الاستعراض على موقع الويب هذا من بين استخداماته العديدة. </p>\r\nتشير <p> <strong> الدولة </strong> إلى: نيو برونزويك ، كندا </p>\r\n<p> <strong> الجهاز </strong> يعني أي جهاز يمكنه الوصول إلى الخدمة مثل جهاز كمبيوتر أو هاتف محمول أو جهاز لوحي رقمي. </p>\r\n<p> <strong> البيانات الشخصية </strong> هي أي معلومات تتعلق بفرد محدد الهوية أو يمكن التعرف عليه. </p>\r\nتشير <p> <strong> الخدمة </strong> إلى موقع الويب. </p>\r\n<p> <strong> مقدم الخدمة </strong> يُقصد به أي شخص طبيعي أو اعتباري يقوم بمعالجة البيانات نيابة عن الشركة. يشير إلى شركات أو أفراد تابعين لجهات خارجية توظفهم الشركة لتسهيل الخدمة ، أو لتقديم الخدمة نيابة عن الشركة ، أو لأداء الخدمات المتعلقة بالخدمة أو لمساعدة الشركة في تحليل كيفية استخدام الخدمة. </p>\r\nتشير <p> <strong> بيانات الاستخدام </strong> إلى البيانات التي يتم جمعها تلقائيًا ، إما الناتجة عن استخدام الخدمة أو من البنية التحتية للخدمة نفسها (على سبيل المثال ، مدة زيارة الصفحة). </p>\r\nيشير <p> <strong> موقع الويب </strong> إلى https://www.ishop.cholobangla.com/ ، ويمكن الوصول إليه من <a href=\"ishop.com\" rel=\"external nofollow noopener\" target=\"_blank\"> ishop.cholobangla.com </a> </p>\r\n<p> <strong> أنت </strong> تعني الفرد الذي يصل إلى الخدمة أو يستخدمها ، أو الشركة أو الكيان القانوني الآخر الذي يصل هذا الفرد إلى الخدمة أو يستخدمها نيابةً عنه ، حسب الاقتضاء. </p>\r\n','Ishop - عن','عن','ar',1,'عن');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (2,'2024-11-19 05:44:41','2024-11-21 17:35:15','التعليمات','<h1 style=\"margin: 30px 0\">  الأسئلة المتداولة </h1>\r\n<h2 style=\"margin: 30px 0\">  نظرة عامة؟ </h2>\r\n<p> ishop عبارة عن تجارة إلكترونية متعددة البائعين تم إنشاء CMS.API باستخدام <b> laravel </b> ، ولوحة الإدارة وتم إنشاء الواجهة الأمامية باستخدام <strong> nuxt js </strong> لتخزين البيانات <b> mysql </ b> قيد الاستخدام. أداء الموقع سريع للغاية بسبب نظام <b> التخزين المؤقت </ b> المتقدم. إنه سريع الاستجابة وقابل للتخصيص بدرجة كبيرة. لن يتم العثور على ملفات إنشاء لوحة إدارة الترخيص العادية ، وهذا يعني أنك لن تتمكن من تخصيص أي تصميم للوحة الإدارة. سيتم العثور على الكود المصدري للواجهة الأمامية وواجهة برمجة التطبيقات في مجلد الحزمة. يمكنك تخصيص الواجهة الأمامية وواجهة برمجة التطبيقات حسب متطلباتك بسهولة بالغة. سيتم العثور على رمز مصدر لوحة المشرف في الترخيص الموسع. لأي استفسار ، يرجى الاتصال بفريقنا للحصول على الدعم على <a href=\"mailto:iyozedcontact@gmail.com\" class=\"link\"> <b> iyozedcontact@gmail.com </b> </a> </p>\r\n<h2 style=\"margin: 30px 0\">  هل نقدم دعم التثبيت للمستخدمين؟ </h2>\r\n<p> نعم ، نحن نقدم دعم التثبيت للمستخدمين. لا تتردد في مراسلتنا عبر البريد الإلكتروني في أي وقت. </p>\r\n<h2 style=\"margin: 30px 0\">  هل نقدم دليل التثبيت للمستخدمين؟ </h2>\r\n<p> نعم ، نحن نقدم دليل التثبيت للمستخدمين مع الحزم. </p>\r\n<h2 style=\"margin: 30px 0\">  كم من الوقت نحتاج للعودة إلى المستخدم؟ </h2>\r\n<p> نقوم بالرد على المستخدمين في أقرب وقت ممكن. </p>\r\n','Ishop - التعليمات','التعليمات','ar',2,'التعليمات');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (3,'2024-11-19 05:44:41','2024-11-21 17:35:15','اتصال','Contact','Ishop - اتصال','اتصال','ar',3,'اتصال');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (4,'2024-11-19 05:44:41','2024-11-21 17:35:15','سياسة الاسترجاع','<h1 style=\"margin: 30px 0\">؛\"> سياسة رد الأموال </h1>\r\n<h2 style=\"margin: 30px 0\">؛\"> تعريفات </h2>\r\n<p> لأغراض سياسة الخصوصية هذه: </p>\r\n<p> <strong> الحساب </strong> يعني حسابًا فريدًا تم إنشاؤه لك للوصول إلى خدمتنا أو أجزاء من خدمتنا. </p>\r\n<p> <strong> الشركة </strong> (يشار إليها باسم & quot؛ الشركة & \"، & quot؛ نحن & quot؛، & quot؛ لنا & quot؛ أو & quot؛ لدينا & quot؛ في هذه الاتفاقية) تشير إلى ishop.cholobangla.com ، كندا. </p>\r\n<p> <strong> ملفات تعريف الارتباط </strong> هي ملفات صغيرة يتم وضعها على جهاز الكمبيوتر أو الجهاز المحمول أو أي جهاز آخر بواسطة موقع ويب ، وتحتوي على تفاصيل محفوظات الاستعراض على موقع الويب هذا من بين استخداماته العديدة. </p>\r\nتشير <p> <strong> الدولة </strong> إلى: نيو برونزويك ، كندا </p>\r\n<p> <strong> الجهاز </strong> يعني أي جهاز يمكنه الوصول إلى الخدمة مثل جهاز كمبيوتر أو هاتف محمول أو جهاز لوحي رقمي. </p>\r\n<p> <strong> البيانات الشخصية </strong> هي أي معلومات تتعلق بفرد محدد الهوية أو يمكن التعرف عليه. </p>\r\nتشير <p> <strong> الخدمة </strong> إلى موقع الويب. </p>\r\n<p> <strong> مقدم الخدمة </strong> يُقصد به أي شخص طبيعي أو اعتباري يقوم بمعالجة البيانات نيابة عن الشركة. يشير إلى شركات أو أفراد تابعين لجهات خارجية توظفهم الشركة لتسهيل الخدمة ، لتقديم الخدمة نيابة عن الشركة ، لأداء الخدمات المتعلقة بالخدمة أو لمساعدة الشركة في تحليل كيفية استخدام الخدمة. </ ص>\r\nتشير <p> <strong> بيانات الاستخدام </strong> إلى البيانات التي يتم جمعها تلقائيًا ، إما الناتجة عن استخدام الخدمة أو من البنية التحتية للخدمة نفسها (على سبيل المثال ، مدة زيارة الصفحة). </p>\r\nيشير <p> <strong> موقع الويب </strong> إلى https: //ishop.cholobangla.com/ ، ويمكن الوصول إليه من <a href=\"ishop.cholobangla.com\" rel=\"external nofollow noopener\" target=\"_blank\"> ishop.cholobangla.com </a> </p>\r\n<p> <strong> أنت </strong> تعني الفرد الذي يصل إلى الخدمة أو يستخدمها ، أو الشركة ، أو الكيان القانوني الآخر الذي يصل هذا الفرد إلى الخدمة أو يستخدمها نيابةً عنه ، حسب الاقتضاء. </p>\r\n<h1 style=\"margin: 30px 0\">؛\"> جمع واستخدام بياناتك الشخصية </h1>\r\n<h2 style=\"margin: 30px 0\">؛\"> أنواع البيانات المجمعة </h2>\r\n<h3 style=\"margin: 30px 0\">؛\"> البيانات الشخصية </h3>\r\n<p> أثناء استخدام خدمتنا ، قد نطلب منك تزويدنا بمعلومات تعريف شخصية معينة يمكن استخدامها للاتصال بك أو التعرف عليك. قد تتضمن معلومات التعريف الشخصية ، على سبيل المثال لا الحصر: </p>\r\n<ul style=\"margin: 30px 0\">؛\"> <li> عنوان البريد الإلكتروني </ li> <li> الاسم الأول واسم العائلة </ li> <li> العنوان والولاية والمقاطعة والرمز البريدي / الرمز البريدي والمدينة </ li> <li> بيانات الاستخدام </ li> </ul>\r\n<h3 style=\"margin: 30px 0\">؛\"> بيانات الاستخدام </h3>\r\n<p> يتم جمع بيانات الاستخدام تلقائيًا عند استخدام الخدمة. </p>\r\n<p> قد تتضمن بيانات الاستخدام معلومات مثل عنوان بروتوكول الإنترنت لجهازك (مثل عنوان IP) ، ونوع المتصفح ، وإصدار المتصفح ، وصفحات الخدمة التي تزورها ، ووقت وتاريخ زيارتك ، والوقت الذي تقضيه في تلك الصفحات ومعرفات الجهاز الفريدة وبيانات التشخيص الأخرى. </p>\r\n<p> عند الوصول إلى الخدمة عن طريق أو من خلال جهاز محمول ، يجوز لنا جمع معلومات معينة تلقائيًا ، بما في ذلك ، على سبيل المثال لا الحصر ، نوع الجهاز المحمول الذي تستخدمه ، والمعرف الفريد لجهازك المحمول ، وعنوان IP لجهازك المحمول ونظام تشغيل هاتفك المحمول ونوع متصفح الإنترنت على الهاتف المحمول الذي تستخدمه ومعرفات الجهاز الفريدة وبيانات التشخيص الأخرى. </p>\r\n<p> قد نجمع أيضًا المعلومات التي يرسلها متصفحك عندما تزور خدمتنا أو عندما تصل إلى الخدمة عن طريق أو من خلال جهاز محمول. </p>\r\n<h3 style=\"margin: 30px 0\">؛\"> تقنيات التتبع وملفات تعريف الارتباط </h3>\r\n<p> نستخدم ملفات تعريف الارتباط وتقنيات التتبع المماثلة لتتبع النشاط على خدمتنا وتخزين معلومات معينة. تقنيات التتبع المستخدمة هي إشارات وعلامات ونصوص لجمع المعلومات وتتبعها ولتحسين خدمتنا وتحليلها. قد تشمل التقنيات التي نستخدمها ما يلي: </p>\r\n<ul style=\"margin: 30px 0\">؛\"> <li> <strong> ملفات تعريف الارتباط أو ملفات تعريف ارتباط المتصفح. </strong> ملف تعريف الارتباط هو ملف صغير يوضع على جهازك. يمكنك توجيه متصفحك لرفض جميع ملفات تعريف الارتباط أو للإشارة إلى وقت إرسال ملف تعريف الارتباط. ومع ذلك ، إذا كنت لا تقبل ملفات تعريف الارتباط ، فقد لا تتمكن من استخدام بعض أجزاء من خدمتنا. ما لم تقم بتعديل إعداد المستعرض الخاص بك بحيث يرفض ملفات تعريف الارتباط ، فقد تستخدم خدمتنا ملفات تعريف الارتباط. </ li> <li> <strong> إشارات الويب. </strong> قد تحتوي أقسام معينة من خدمتنا ورسائل البريد الإلكتروني الخاصة بنا على ملفات إلكترونية صغيرة تُعرف باسم إشارات الويب (يشار إليها أيضًا باسم gifs الواضحة وعلامات البكسل وصور gif أحادية البكسل) التي تسمح للشركة ، على سبيل المثال ، بإحصاء المستخدمين الذين زاروا تلك الصفحات أو فتحوا بريدًا إلكترونيًا ولإحصائيات مواقع الويب الأخرى ذات الصلة (على سبيل المثال وتسجيل شعبية قسم معين والتحقق من سلامة النظام والخادم). </ li> </ul>\r\n<p> يمكن أن تكون ملفات تعريف الارتباط & quot؛ ثابتة & quot؛ أو & quot؛ جلسة & quot؛ بسكويت. تظل ملفات تعريف الارتباط الدائمة على جهاز الكمبيوتر الشخصي أو الجهاز المحمول الخاص بك عندما تكون غير متصل بالإنترنت ، بينما يتم حذف ملفات تعريف ارتباط الجلسة بمجرد إغلاق متصفح الويب الخاص بك. تعرف على المزيد حول ملفات تعريف الارتباط على مقالة <a href= \"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\"> موقع ويب سياسة الخصوصية المجانية </a>. </p>\r\n<p> نستخدم كلاً من ملفات تعريف الارتباط الخاصة بالجلسة وملفات تعريف الارتباط الدائمة للأغراض الموضحة أدناه: </p >\r\n<p> <strong> ملفات تعريف الارتباط الضرورية / الأساسية </strong> </p>\r\n<p> النوع: ملفات تعريف ارتباط الجلسة </p>\r\n<p> تحت إدارة: نحن </p>\r\n<p> الغرض: ملفات تعريف الارتباط هذه ضرورية لتزويدك بالخدمات المتاحة عبر موقع الويب ولتمكينك من استخدام بعض ميزاته. إنها تساعد في مصادقة المستخدمين ومنع الاستخدام الاحتيالي لحسابات المستخدمين. بدون ملفات تعريف الارتباط هذه ، لا يمكن توفير الخدمات التي طلبتها ، ونحن نستخدم ملفات تعريف الارتباط هذه فقط لتزويدك بهذه الخدمات. </p>\r\n<p> <strong> سياسة ملفات تعريف الارتباط / ملفات تعريف ارتباط قبول الإشعار </strong> </p>\r\n<p> النوع: ملفات تعريف الارتباط الدائمة </p>\r\n<p> تحت إدارة: نحن </p>\r\n<p> الغرض: تحدد ملفات تعريف الارتباط هذه ما إذا كان المستخدمون قد وافقوا على استخدام ملفات تعريف الارتباط على موقع الويب. </p>\r\n<p> <strong> ملفات تعريف الارتباط الوظيفية </strong> </p>\r\n<p> النوع: ملفات تعريف الارتباط الدائمة </p>\r\n<p> تحت إدارة: نحن </p>\r\n<p> الغرض: تسمح لنا ملفات تعريف الارتباط هذه بتذكر الاختيارات التي تقوم بها عند استخدام موقع الويب ، مثل تذكر تفاصيل تسجيل الدخول أو تفضيلات اللغة. الغرض من ملفات تعريف الارتباط هذه هو تزويدك بتجربة شخصية أكثر وتجنب الاضطرار إلى إعادة إدخال تفضيلاتك في كل مرة تستخدم فيها موقع الويب. </p>\r\n<p> لمزيد من المعلومات حول ملفات تعريف الارتباط التي نستخدمها وخياراتك فيما يتعلق بملفات تعريف الارتباط ، يرجى زيارة سياسة ملفات تعريف الارتباط أو قسم ملفات تعريف الارتباط في سياسة الخصوصية الخاصة بنا. </p>\r\n<h2 style=\"margin: 30px 0\">؛\"> استخدام بياناتك الشخصية </h2>\r\n<p> يجوز للشركة استخدام البيانات الشخصية للأغراض التالية: </p>\r\n<p> <strong> لتقديم خدمتنا وصيانتها </strong> ، بما في ذلك مراقبة استخدام خدمتنا. </p>\r\n<p> <strong> لإدارة حسابك: </strong> لإدارة تسجيلك كمستخدم للخدمة. يمكن أن تمنحك البيانات الشخصية التي تقدمها إمكانية الوصول إلى الوظائف المختلفة للخدمة المتاحة لك كمستخدم مسجل. </p>\r\n<p> <strong> لتنفيذ عقد: </strong> التطوير والامتثال والتعهد بعقد شراء المنتجات أو العناصر أو الخدمات التي اشتريتها أو أي عقد آخر معنا من خلال الخدمة. </ ص>\r\n<p> <strong> للاتصال بك: </strong> للاتصال بك عن طريق البريد الإلكتروني أو المكالمات الهاتفية أو الرسائل القصيرة أو غير ذلك من أشكال الاتصالات الإلكترونية المماثلة ، مثل الإخطارات الفورية لتطبيقات الهاتف المحمول فيما يتعلق بالتحديثات أو الاتصالات الإعلامية المتعلقة بالوظائف ، المنتجات أو الخدمات المتعاقد عليها ، بما في ذلك التحديثات الأمنية ، عند الضرورة أو المعقول لتنفيذها. </p>\r\n<p> <strong> لتزويدك </strong> بأخبار وعروض خاصة ومعلومات عامة حول السلع والخدمات والأحداث الأخرى التي نقدمها والتي تشبه تلك التي اشتريتها بالفعل أو استفسرت عنها ما لم تكن قد اخترت عدم تلقي هذه المعلومات. </p>\r\n<p> <strong> لإدارة طلباتك: </strong> لحضور وإدارة طلباتك إلينا. </p>\r\n<p> <strong> لعمليات نقل الأعمال: </strong> قد نستخدم معلوماتك لتقييم أو إجراء عملية دمج أو تجريد أو إعادة هيكلة أو إعادة تنظيم أو حل أو غير ذلك من عمليات البيع أو النقل لبعض أو كل أصولنا ، سواء كانت الاستمرارية أو كجزء من الإفلاس أو التصفية أو الإجراءات المماثلة ، حيث تكون البيانات الشخصية التي نحتفظ بها حول مستخدمي خدمتنا من بين الأصول المنقولة. </p>\r\n<p> <strong> لأغراض أخرى </strong>: قد نستخدم معلوماتك لأغراض أخرى ، مثل تحليل البيانات ، وتحديد اتجاهات الاستخدام ، وتحديد فعالية حملاتنا الترويجية ولتقييم وتحسين خدماتنا ومنتجاتنا وخدماتنا والتسويق وتجربتك. </p>\r\n\r\n','Ishop - سياسة الاسترجاع','سياسة الاسترجاع','ar',4,'سياسة,الاسترجاع');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (5,'2024-11-19 05:44:41','2024-11-21 17:35:15','سياسة الخصوصية','<h1 style = \"margin: 30px 0\"> سياسة الخصوصية </h1>\r\n<p> آخر تحديث : 13 كانون الأول (ديسمبر) 2022 </p>\r\n<p> تصف سياسة الخصوصية هذه سياساتنا وإجراءاتنا المتعلقة بجمع معلوماتك واستخدامها والكشف عنها عند استخدامك للخدمة وتخبرك بحقوق الخصوصية الخاصة بك وكيف يحميك القانون. </p>\r\n<p> نستخدم بياناتك الشخصية لتوفير الخدمة وتحسينها. باستخدام الخدمة ، فإنك توافق على جمع واستخدام المعلومات وفقًا لسياسة الخصوصية هذه. تم إنشاء سياسة الخصوصية هذه بمساعدة <a href = \"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\" target=\"_blank\"> أداة إنشاء سياسة الخصوصية المجانية </a>. </p>\r\n<h1 style = \"margin: 30px 0\"> التفسير والتعريفات </h1>\r\n<h2 style = \"margin: 30px 0\"> تفسير </h2>\r\n<p> الكلمات التي يتم كتابة الحرف الأول بها معاني محددة وفقًا للشروط التالية. يجب أن يكون للتعريفات التالية نفس المعنى بغض النظر عما إذا كانت تظهر بصيغة المفرد أو الجمع. </p>\r\n<h2 style = \"margin: 30px 0\"> تعريفات </h2>\r\n<p> لأغراض سياسة الخصوصية هذه : </p>\r\n<strong> الحساب </strong> يعني حسابًا فريدًا تم إنشاؤه لك للوصول إلى خدمتنا أو أجزاء من خدمتنا. </p>\r\n<p> <strong> الشركة </strong> (يشار إليها باسم & quot؛ الشركة & \"، & quot؛ نحن & quot؛، & quot؛ لنا & quot؛ أو & quot؛ لدينا & quot؛ في هذه الاتفاقية) تشير إلى ishop.cholobangla.com ، كندا. </p>\r\n<p> <strong> ملفات تعريف الارتباط </strong> هي ملفات صغيرة يتم وضعها على جهاز الكمبيوتر أو الجهاز المحمول أو أي جهاز آخر بواسطة موقع ويب ، وتحتوي على تفاصيل محفوظات الاستعراض على موقع الويب هذا من بين استخداماته العديدة. </p>\r\nتشير <p> <strong> الدولة </strong> إلى : نيو برونزويك ، كندا </p>\r\n<p> <strong> الجهاز </strong> يعني أي جهاز يمكنه الوصول إلى الخدمة مثل جهاز كمبيوتر أو هاتف محمول أو جهاز لوحي رقمي. </p>\r\n<p> <strong> البيانات الشخصية </strong> هي أي معلومات تتعلق بفرد محدد الهوية أو يمكن التعرف عليه. </p>\r\nتشير <p> <strong> الخدمة </strong> إلى موقع الويب. </p>\r\n<p> <strong> مقدم الخدمة </strong> يُقصد به أي شخص طبيعي أو اعتباري يقوم بمعالجة البيانات نيابة عن الشركة. يشير إلى شركات أو أفراد تابعين لجهات خارجية توظفهم الشركة لتسهيل الخدمة ، لتقديم الخدمة نيابة عن الشركة ، لأداء الخدمات المتعلقة بالخدمة أو لمساعدة الشركة في تحليل كيفية استخدام الخدمة. </ ص>\r\nتشير <p> <strong> بيانات الاستخدام </strong> إلى البيانات التي يتم جمعها تلقائيًا ، إما الناتجة عن استخدام الخدمة أو من البنية التحتية للخدمة نفسها (على سبيل المثال ، مدة زيارة الصفحة). </p>\r\nيشير <p> <strong> موقع الويب </strong> إلى https : //ishop.cholobangla.com/ ، ويمكن الوصول إليه من <a href=\"ishop.cholobangla.com\" rel=\"external nofollow noopener\" target=\"_blank\"> ishop.cholobangla.com </a> </p>\r\n<p> <strong> أنت </strong> تعني الفرد الذي يصل إلى الخدمة أو يستخدمها ، أو الشركة ، أو الكيان القانوني الآخر الذي يصل هذا الفرد إلى الخدمة أو يستخدمها نيابةً عنه ، حسب الاقتضاء. </p>\r\n<h1 style = \"margin: 30px 0\"> جمع واستخدام بياناتك الشخصية </h1>\r\n<h2 style = \"margin: 30px 0\"> أنواع البيانات المجمعة </h2>\r\n<h3 style = \"margin: 30px 0\"> البيانات الشخصية </h3>\r\n<p> أثناء استخدام خدمتنا ، قد نطلب منك تزويدنا بمعلومات تعريف شخصية معينة يمكن استخدامها للاتصال بك أو التعرف عليك. قد تتضمن معلومات التعريف الشخصية ، على سبيل المثال لا الحصر : </p>\r\n<ul style = \"margin: 30px 0\"> <li> عنوان البريد الإلكتروني </ li> <li> الاسم الأول واسم العائلة </ li> <li> العنوان والولاية والمقاطعة والرمز البريدي / الرمز البريدي والمدينة </ li> <li> بيانات الاستخدام </ li> </ul>\r\n<h3 style = \"margin: 30px 0\"> بيانات الاستخدام </h3>\r\n<p> يتم جمع بيانات الاستخدام تلقائيًا عند استخدام الخدمة. </p>\r\n<p> قد تتضمن بيانات الاستخدام معلومات مثل عنوان بروتوكول الإنترنت لجهازك (مثل عنوان IP) ، ونوع المتصفح ، وإصدار المتصفح ، وصفحات الخدمة التي تزورها ، ووقت وتاريخ زيارتك ، والوقت الذي تقضيه في تلك الصفحات ومعرفات الجهاز الفريدة وبيانات التشخيص الأخرى. </p>\r\n<p> عند الوصول إلى الخدمة عن طريق أو من خلال جهاز محمول ، يجوز لنا جمع معلومات معينة تلقائيًا ، بما في ذلك ، على سبيل المثال لا الحصر ، نوع الجهاز المحمول الذي تستخدمه ، والمعرف الفريد لجهازك المحمول ، وعنوان IP لجهازك المحمول ونظام تشغيل هاتفك المحمول ونوع متصفح الإنترنت على الهاتف المحمول الذي تستخدمه ومعرفات الجهاز الفريدة وبيانات التشخيص الأخرى. </p>\r\n<p> قد نجمع أيضًا المعلومات التي يرسلها متصفحك عندما تزور خدمتنا أو عندما تصل إلى الخدمة عن طريق أو من خلال جهاز محمول. </p>\r\n<h3 style = \"margin: 30px 0\"> تقنيات التتبع وملفات تعريف الارتباط </h3>\r\n<p> نستخدم ملفات تعريف الارتباط وتقنيات التتبع المماثلة لتتبع النشاط على خدمتنا وتخزين معلومات معينة. تقنيات التتبع المستخدمة هي إشارات وعلامات ونصوص لجمع المعلومات وتتبعها ولتحسين خدمتنا وتحليلها. قد تشمل التقنيات التي نستخدمها ما يلي : </p>\r\n<p> <strong> ملفات تعريف الارتباط أو ملفات تعريف ارتباط المتصفح. </strong> ملف تعريف الارتباط هو ملف صغير يوضع على جهازك. يمكنك توجيه متصفحك لرفض جميع ملفات تعريف الارتباط أو للإشارة إلى وقت إرسال ملف تعريف الارتباط. ومع ذلك ، إذا كنت لا تقبل ملفات تعريف الارتباط ، فقد لا تتمكن من استخدام بعض أجزاء من خدمتنا. ما لم تقم بتعديل إعدادات المتصفح بحيث يرفض ملفات تعريف الارتباط ، فقد تستخدم خدمتنا ملفات تعريف الارتباط. </p>\r\n<p> <strong> إشارات الويب. </strong> قد تحتوي أقسام معينة من خدمتنا ورسائل البريد الإلكتروني الخاصة بنا على ملفات إلكترونية صغيرة تُعرف بإشارات الويب (يُشار إليها أيضًا باسم gifs الواضحة وعلامات البكسل وصور GIF أحادية البكسل) التي تسمح للشركة ، على سبيل المثال ، لحساب عدد المستخدمين الذين زاروا هذه الصفحات أو فتحوا بريدًا إلكترونيًا ولإحصائيات مواقع الويب الأخرى ذات الصلة (على سبيل المثال ، تسجيل شعبية قسم معين والتحقق من سلامة النظام والخادم). </p>\r\n<p> يمكن أن تكون ملفات تعريف الارتباط & quot؛ ثابتة & quot؛ أو & quot؛ جلسة & quot؛ بسكويت. تظل ملفات تعريف الارتباط الدائمة على جهاز الكمبيوتر الشخصي أو الجهاز المحمول الخاص بك عندما تكون غير متصل بالإنترنت ، بينما يتم حذف ملفات تعريف ارتباط الجلسة بمجرد إغلاق متصفح الويب الخاص بك. تعرف على المزيد حول ملفات تعريف الارتباط على مقالة <a href = \"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\"> موقع ويب سياسة الخصوصية المجانية </a>. </p>\r\n<p> نستخدم كلاً من ملفات تعريف الارتباط الخاصة بالجلسة وملفات تعريف الارتباط الدائمة للأغراض الموضحة أدناه : </p>\r\n<p> <strong> ملفات تعريف الارتباط الضرورية / الأساسية </strong> </p>\r\n<p> النوع : ملفات تعريف ارتباط الجلسة </p>\r\n<p> تحت إدارة : نحن </p>\r\n<p> الغرض : ملفات تعريف الارتباط هذه ضرورية لتزويدك بالخدمات المتاحة عبر موقع الويب ولتمكينك من استخدام بعض ميزاته. إنها تساعد في مصادقة المستخدمين ومنع الاستخدام الاحتيالي لحسابات المستخدمين. بدون ملفات تعريف الارتباط هذه ، لا يمكن توفير الخدمات التي طلبتها ، ونحن نستخدم ملفات تعريف الارتباط هذه فقط لتزويدك بهذه الخدمات. </p>\r\n<p> <strong> سياسة ملفات تعريف الارتباط / ملفات تعريف ارتباط قبول الإشعار </strong> </p>\r\n<p> النوع : ملفات تعريف الارتباط الدائمة </p>\r\n<p> تحت إدارة : نحن </p>\r\n<p> الغرض : تحدد ملفات تعريف الارتباط هذه ما إذا كان المستخدمون قد وافقوا على استخدام ملفات تعريف الارتباط على موقع الويب. </p>\r\n<p> <strong> ملفات تعريف الارتباط الوظيفية </strong> </p>\r\n<p> النوع : ملفات تعريف الارتباط الدائمة </p>\r\n<p> تحت إدارة : نحن </p>\r\n<p> الغرض : تسمح لنا ملفات تعريف الارتباط هذه بتذكر الاختيارات التي تقوم بها عند استخدام موقع الويب ، مثل تذكر تفاصيل تسجيل الدخول أو تفضيلات اللغة. الغرض من ملفات تعريف الارتباط هذه هو تزويدك بتجربة شخصية أكثر وتجنب الاضطرار إلى إعادة إدخال تفضيلاتك في كل مرة تستخدم فيها موقع الويب. </p>\r\n<p> لمزيد من المعلومات حول ملفات تعريف الارتباط التي نستخدمها وخياراتك فيما يتعلق بملفات تعريف الارتباط ، يرجى زيارة سياسة ملفات تعريف الارتباط أو قسم ملفات تعريف الارتباط في سياسة الخصوصية الخاصة بنا. </p>\r\n<h2 style = \"margin: 30px 0\"> استخدام بياناتك الشخصية </h2>\r\n<p> يجوز للشركة استخدام البيانات الشخصية للأغراض التالية : </p>\r\n<p> <strong> لتقديم خدمتنا وصيانتها </strong> ، بما في ذلك مراقبة استخدام خدمتنا. </p>\r\n<p> <strong> لإدارة حسابك : </strong> لإدارة تسجيلك كمستخدم للخدمة. يمكن أن تمنحك البيانات الشخصية التي تقدمها إمكانية الوصول إلى الوظائف المختلفة للخدمة المتاحة لك كمستخدم مسجل. </p>\r\n<p> <strong> لتنفيذ عقد : </strong> التطوير والامتثال والتعهد بعقد شراء المنتجات أو العناصر أو الخدمات التي اشتريتها أو أي عقد آخر معنا من خلال الخدمة. </ ص>\r\n<p> <strong> للاتصال بك : </strong> للاتصال بك عن طريق البريد الإلكتروني أو المكالمات الهاتفية أو الرسائل القصيرة أو غير ذلك من أشكال الاتصالات الإلكترونية المماثلة ، مثل الإخطارات الفورية لتطبيقات الهاتف المحمول فيما يتعلق بالتحديثات أو الاتصالات الإعلامية المتعلقة بالوظائف ، المنتجات أو الخدمات المتعاقد عليها ، بما في ذلك التحديثات الأمنية ، عند الضرورة أو المعقول لتنفيذها. </p>\r\n<p> <strong> لتزويدك </strong> بأخبار وعروض خاصة ومعلومات عامة حول السلع والخدمات والأحداث الأخرى التي نقدمها والتي تشبه تلك التي اشتريتها بالفعل أو استفسرت عنها ما لم تكن قد اخترت عدم تلقي هذه المعلومات. </p>\r\n<p> <strong> لإدارة طلباتك : </strong> لحضور وإدارة طلباتك إلينا. </p>\r\n<p> <strong> لعمليات نقل الأعمال : </strong> قد نستخدم معلوماتك لتقييم أو إجراء عملية دمج أو تجريد أو إعادة هيكلة أو إعادة تنظيم أو حل أو غير ذلك من عمليات البيع أو النقل لبعض أو كل أصولنا ، سواء كانت الاستمرارية أو كجزء من الإفلاس أو التصفية أو الإجراءات المماثلة ، حيث تكون البيانات الشخصية التي نحتفظ بها حول مستخدمي خدمتنا من بين الأصول المنقولة. </p>\r\n<p> <strong> لأغراض أخرى </strong> : قد نستخدم معلوماتك لأغراض أخرى ، مثل تحليل البيانات ، وتحديد اتجاهات الاستخدام ، وتحديد فعالية حملاتنا الترويجية ولتقييم وتحسين خدماتنا ومنتجاتنا وخدماتنا والتسويق وتجربتك. </p>\r\n<p> قد نشارك معلوماتك الشخصية في المواقف التالية : </p>\r\n<ul style = \"margin: 30px 0\"> <li> <strong> مع مزودي الخدمة: </strong> قد نشارك معلوماتك الشخصية مع مزودي الخدمة لمراقبة وتحليل استخدام خدمتنا ، للاتصال بك. < / li> <li> <strong> لعمليات نقل الأعمال: </strong> يجوز لنا مشاركة معلوماتك الشخصية أو نقلها فيما يتعلق أو أثناء المفاوضات بشأن أي دمج أو بيع أصول الشركة أو التمويل أو الاستحواذ على كل أو جزء من أعمالنا إلى شركة أخرى. </ li> <li> <strong> مع الشركات التابعة: </strong> قد نشارك معلوماتك مع الشركات التابعة لنا ، وفي هذه الحالة سنطلب من تلك الشركات التابعة احترام سياسة الخصوصية هذه. تشمل الشركات التابعة شركتنا الأم وأي شركات فرعية أخرى أو شركاء في المشاريع المشتركة أو شركات أخرى نسيطر عليها أو تخضع لسيطرة مشتركة معنا. </ li> <li> <strong> مع شركاء الأعمال: </strong> قد نشاركك المعلومات مع شركائنا في العمل لنقدم لك منتجات أو خدمات أو عروض ترويجية معينة. </ li> <li> <strong> مع مستخدمين آخرين: </strong> عندما تشارك معلومات شخصية أو تتفاعل بطريقة أخرى في المناطق العامة مع مستخدمين آخرين ، مثل يمكن عرض المعلومات من قبل جميع المستخدمين ويمكن توزيعها علنًا في الخارج. </ li> <li> <strong> بموافقتك </strong>: يجوز لنا الكشف عن معلوماتك الشخصية لأي غرض آخر بموافقتك. </ li> </ul>\r\n<h2 style = \"margin: 30px 0\"> الاحتفاظ ببياناتك الشخصية </h2>\r\n<p> ستحتفظ الشركة ببياناتك الشخصية فقط طالما كان ذلك ضروريًا للأغراض المنصوص عليها في سياسة الخصوصية هذه. سنحتفظ ببياناتك الشخصية ونستخدمها بالقدر اللازم للامتثال لالتزاماتنا القانونية (على سبيل المثال ، إذا طُلب منا الاحتفاظ ببياناتك للامتثال للقوانين المعمول بها) ، وحل النزاعات ، وإنفاذ اتفاقياتنا وسياساتنا القانونية. </ ص>\r\n<p> ستحتفظ الشركة أيضًا ببيانات الاستخدام لأغراض التحليل الداخلي. بشكل عام ، يتم الاحتفاظ ببيانات الاستخدام لفترة زمنية أقصر ، إلا في حالة استخدام هذه البيانات لتعزيز الأمن أو لتحسين وظائف خدمتنا ، أو نحن ملزمون قانونًا بالاحتفاظ بهذه البيانات لفترات زمنية أطول. </p>\r\n<h2 style = \"margin: 30px 0\"> نقل بياناتك الشخصية </h2>\r\n<p> تتم معالجة معلوماتك ، بما في ذلك البيانات الشخصية ، في مكاتب تشغيل الشركة وفي أي أماكن أخرى توجد بها الأطراف المشاركة في المعالجة. وهذا يعني أنه قد يتم نقل هذه المعلومات إلى - والاحتفاظ بها - على أجهزة الكمبيوتر الموجودة خارج ولايتك أو مقاطعتك أو بلدك أو أي ولاية قضائية حكومية أخرى حيث قد تختلف قوانين حماية البيانات عن تلك الموجودة في ولايتك القضائية. </p>\r\n<p> موافقتك على سياسة الخصوصية هذه متبوعة بتقديمك لهذه المعلومات يمثل موافقتك على هذا النقل. </p>\r\n<p> ستتخذ الشركة جميع الخطوات اللازمة بشكل معقول لضمان التعامل مع بياناتك بشكل آمن ووفقًا لسياسة الخصوصية هذه ولن يتم نقل بياناتك الشخصية إلى منظمة أو دولة ما لم تكن هناك ضوابط كافية مطبقة بما في ذلك أمان بياناتك والمعلومات الشخصية الأخرى. </p>\r\n<h2 style = \"margin: 30px 0\"> حذف بياناتك الشخصية </h2>\r\n<p> لديك الحق في حذف أو طلب مساعدتنا في حذف البيانات الشخصية التي جمعناها عنك. </p>\r\n<p> قد تمنحك خدمتنا القدرة على حذف معلومات معينة عنك من داخل الخدمة. </p>\r\n<p> يمكنك تحديث معلوماتك أو تعديلها أو حذفها في أي وقت عن طريق تسجيل الدخول إلى حسابك ، إذا كان لديك حساب ، وزيارة قسم إعدادات الحساب الذي يسمح لك بإدارة معلوماتك الشخصية. يمكنك أيضًا الاتصال بنا لطلب الوصول إلى أي معلومات شخصية قدمتها لنا أو تصحيحها أو حذفها. </p>\r\n<p> ومع ذلك ، يرجى ملاحظة أننا قد نحتاج إلى الاحتفاظ بمعلومات معينة عندما يكون لدينا التزام قانوني أو أساس قانوني للقيام بذلك. </p>\r\n<h2 style = \"margin: 30px 0\"> الكشف عن بياناتك الشخصية </h2>\r\n<h3 style = \"margin: 30px 0\"> المعاملات التجارية </h3>\r\n<p> إذا كانت الشركة متورطة في عملية دمج أو استحواذ أو بيع أصول ، فقد يتم نقل بياناتك الشخصية. سنقدم إشعارًا قبل نقل بياناتك الشخصية وخضوعها لسياسة خصوصية مختلفة. </p>\r\n<h3 style = \"margin: 30px 0\"> تطبيق القانون </h3>\r\n<p> في ظل ظروف معينة ، قد يُطلب من الشركة الكشف عن بياناتك الشخصية إذا طُلب منها ذلك بموجب القانون أو استجابة لطلبات صحيحة من قبل السلطات العامة (مثل محكمة أو وكالة حكومية). </p>\r\n<h3 style = \"margin: 30px 0\"> متطلبات قانونية أخرى </h3>\r\n<p> قد تفصح الشركة عن بياناتك الشخصية بحسن نية أن هذا الإجراء ضروري من أجل : </p>\r\n<ul> <li> الامتثال لالتزام قانوني </ li> <li> حماية حقوق أو ممتلكات الشركة والدفاع عنها </ li> <li> منع المخالفات المحتملة المتعلقة بالخدمة أو التحقيق فيها </ li> < li> حماية السلامة الشخصية لمستخدمي الخدمة أو الجمهور </ li> <li> الحماية من المسؤولية القانونية </ li> </ul>\r\n<h2> أمان بياناتك الشخصية </h2>\r\n<p> يعد أمان بياناتك الشخصية أمرًا مهمًا بالنسبة لنا ، ولكن تذكر أنه لا توجد طريقة نقل عبر الإنترنت أو طريقة تخزين إلكتروني آمنة بنسبة 100٪. بينما نسعى جاهدين لاستخدام وسائل مقبولة تجاريًا لحماية بياناتك الشخصية ، لا يمكننا ضمان أمنها المطلق. </p>\r\n<h1> خصوصية الأطفال </h1>\r\n<p> لا تخاطب خدمتنا أي شخص يقل عمره عن 13 عامًا. نحن لا نجمع عن قصد معلومات تعريف شخصية من أي شخص يقل عمره عن 13 عامًا. إذا كنت أحد الوالدين أو الوصي وتدرك أن طفلك قد زودنا بمعلومات شخصية البيانات ، يرجى الاتصال بنا. إذا علمنا أننا قد جمعنا بيانات شخصية من أي شخص يقل عمره عن 13 عامًا دون التحقق من موافقة الوالدين ، فإننا نتخذ خطوات لإزالة هذه المعلومات من خوادمنا. </p>\r\n<p> إذا احتجنا إلى الاعتماد على الموافقة كأساس قانوني لمعالجة معلوماتك وكان بلدك يتطلب موافقة أحد الوالدين ، فقد نطلب موافقة والديك قبل أن نجمع هذه المعلومات ونستخدمها. </p>\r\n<h1 style = \"margin: 30px 0\"> روابط لمواقع أخرى </h1>\r\n<p> قد تحتوي خدمتنا على روابط لمواقع أخرى لا نقوم بتشغيلها. إذا قمت بالنقر فوق ارتباط جهة خارجية ، فسيتم توجيهك إلى موقع الطرف الثالث. ننصحك بشدة بمراجعة سياسة الخصوصية لكل موقع تزوره. </p>\r\n<p> ليس لدينا أي سيطرة ولا نتحمل أي مسؤولية عن المحتوى أو سياسات الخصوصية أو ممارسات أي مواقع أو خدمات تابعة لجهات خارجية. </p>\r\n<h1 style = \"margin: 30px 0\"> التغييرات في سياسة الخصوصية هذه </h1>\r\n<p> قد نقوم بتحديث سياسة الخصوصية الخاصة بنا من وقت لآخر. سنخطرك بأي تغييرات عن طريق نشر سياسة الخصوصية الجديدة على هذه الصفحة. </p>\r\n<p> سنخبرك عبر البريد الإلكتروني و / أو إشعارًا بارزًا على \"خدمتنا\" ، قبل أن يصبح التغيير ساريًا ونقوم بتحديث & quot؛ آخر تحديث & quot؛ التاريخ في الجزء العلوي من سياسة الخصوصية هذه. </p>\r\n<p> يُنصح بمراجعة سياسة الخصوصية هذه بشكل دوري لمعرفة أي تغييرات. تسري التغييرات التي تطرأ على سياسة الخصوصية هذه عند نشرها على هذه الصفحة. </p>\r\n<h1 style = \"margin: 30px 0\"> اتصل بنا </h1>\r\n<p> إذا كان لديك أي أسئلة حول سياسة الخصوصية هذه ، يمكنك الاتصال بنا : </p>\r\n<ul style = \"margin: 30px 0\"> <li> من خلال زيارة هذه الصفحة على موقعنا على الويب: <a href = \"https://ishop.cholobangla.com/\" rel = \"external nofollow noopener\" target = \"_ blank \"> https://ishop.cholobangla.com/ </a> </li> </ul>\r\n\r\n','Ishop - سياسة الخصوصية','سياسة الخصوصية','ar',5,'سياسة,الخصوصية');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (6,'2024-11-19 05:44:41','2024-11-21 17:35:15','يساعد','<h1 style=\"margin: 30px 0;\">مساعدة</h1>\r\n<p> تصف سياسة الخصوصية هذه سياساتنا وإجراءاتنا المتعلقة بجمع معلوماتك واستخدامها والكشف عنها عند استخدامك للخدمة وتخبرك بحقوق الخصوصية الخاصة بك وكيف يحميك القانون. </p>\r\n<p> نستخدم بياناتك الشخصية لتوفير الخدمة وتحسينها. باستخدام الخدمة ، فإنك توافق على جمع واستخدام المعلومات وفقًا لسياسة الخصوصية هذه. تم إنشاء سياسة الخصوصية هذه بمساعدة <a href = \"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\" target=\"_blank\"> أداة إنشاء سياسة الخصوصية المجانية </a>. </p>\r\n<h1 style=\"margin: 30px 0;\">التفسير والتعريفات</h1>\r\n<h2 style=\"margin: 30px 0;\"> تفسير </h2>\r\n<p> الكلمات التي يتم كتابة الحرف الأول بها معاني محددة وفقًا للشروط التالية. يجب أن يكون للتعريفات التالية نفس المعنى بغض النظر عما إذا كانت تظهر بصيغة المفرد أو الجمع. </p>\r\n<h2 style=\"margin: 30px 0;\"> تعريفات </h2>\r\n<p> لأغراض سياسة الخصوصية هذه : </p>\r\n<p> <strong> الحساب </strong> يعني حسابًا فريدًا تم إنشاؤه لك للوصول إلى خدمتنا أو أجزاء من خدمتنا. </p>\r\n<p> <strong> الشركة </strong> (يشار إليها باسم & quot؛ الشركة & \"، & quot؛ نحن & quot؛ أو & quot؛ لنا & quot؛ أو & quot؛ في هذه الاتفاقية) تشير إلى ishop.cholobangla.com ، كندا. </p>\r\n<p> <strong> ملفات تعريف الارتباط </strong> هي ملفات صغيرة يتم وضعها على جهاز الكمبيوتر أو الجهاز المحمول أو أي جهاز آخر بواسطة موقع ويب ، وتحتوي على تفاصيل محفوظات الاستعراض على موقع الويب هذا من بين استخداماته العديدة. </p>\r\nتشير <p> <strong> الدولة </strong> إلى : نيو برونزويك ، كندا </p>\r\n<p> <strong> الجهاز </strong> يعني أي جهاز يمكنه الوصول إلى الخدمة مثل جهاز كمبيوتر أو هاتف ذكي أو جهاز لوحي رقمي. </p>\r\n<p> <strong> البيانات الشخصية </strong> هي أي معلومات تتعلق بفرد محدد الهوية أو يمكن التعرف عليه. </p>\r\nتشير <p> <strong> الخدمة </strong> إلى موقع الويب. </p>\r\n<p> <strong> مقدم الخدمة </strong> يُقصد به أي شخص طبيعي أو اعتباري يقوم بمعالجة البيانات نيابة عن الشركة. يشير إلى شركات أو أفراد تابعين لجهات خارجية توظفهم الشركة لتسهيل الخدمة ، لتقديم الخدمة نيابة عن الشركة ، لأداء الخدمات المتعلقة بالخدمة أو لمساعدة الشركة في تحليل كيفية استخدام الخدمة. </ ص>\r\nتشير <p> <strong> بيانات الاستخدام </strong> إلى البيانات التي يتم جمعها تلقائيًا ، إما الناتجة عن استخدام الخدمة أو من البنية التحتية للخدمة نفسها (على سبيل المثال ، مدة زيارة الصفحة). </p>\r\nيشير <p> <strong> موقع الويب </strong> إلى https : //ishop.cholobangla.com/ ، ويمكن الوصول إليه من <a href=\"ishop.cholobangla\" rel=\"external nofollow noopener\" target=\"_blank\"> ishop. cholobangla.com </a> </p>\r\n<p> <strong> أنت </strong> تعني الفرد الذي يصل إلى الخدمة أو يستخدمها ، أو الشركة أو الكيان القانوني الآخر الذي يصل هذا الفرد إلى الخدمة أو يستخدمها نيابةً عنه ، حسب الاقتضاء. </p>\r\n<h1 style = \"margin: 30px 0 جمع واستخدام بياناتك الشخصية </h1>\r\n<h1 style=\"margin: 30px 0;\"> أنواع البيانات المجمعة </h2>\r\n<h3 style=\"margin: 30px 0;\">البيانات الشخصية </h3>\r\n<p> أثناء استخدام خدمتنا ، قد نطلب منك تزويدنا بمعلومات تعريف شخصية معينة يمكن استخدامها للاتصال بك أو التعرف عليك. قد تتضمن معلومات التعريف الشخصية ، على سبيل المثال لا الحصر : </p>\r\n<ul style = \"margin: 30px 0\"> <li> عنوان البريد الإلكتروني </ li> <li> الاسم الأول واسم العائلة </ li> <li> العنوان والولاية والمقاطعة والرمز البريدي / الرمز البريدي والمدينة </ li> <li> بيانات الاستخدام </ li> </ul>\r\n<h3 style=\"margin: 30px 0;\">بيانات الاستخدام </h3>\r\n<p> يتم جمع بيانات الاستخدام تلقائيًا عند استخدام الخدمة. </p> <p> قد تتضمن بيانات الاستخدام معلومات مثل عنوان بروتوكول الإنترنت لجهازك (مثل عنوان IP) ، ونوع المتصفح ، وإصدار المتصفح ، وصفحات خدمتنا التي أنت تزور ووقت وتاريخ زيارتك والوقت الذي تقضيه في تلك الصفحات ومعرفات الجهاز الفريدة وبيانات التشخيص الأخرى. </p> <p> عند الوصول إلى الخدمة عن طريق أو من خلال جهاز محمول ، يجوز لنا جمع معلومات معينة تلقائيًا ، بما في ذلك ، على سبيل المثال لا الحصر ، نوع الجهاز المحمول الذي تستخدمه ، والمعرف الفريد لجهازك المحمول ، وعنوان IP لجهازك المحمول ، ونظام تشغيل هاتفك المحمول ، ونوع متصفح الإنترنت على الهاتف المحمول الذي تستخدمه ، ومعرفات الجهاز الفريدة وغيرها من التشخيصات البيانات. </p>\r\n<p> قد نجمع أيضًا المعلومات التي يرسلها متصفحك عندما تزور خدمتنا أو عندما تصل إلى الخدمة عن طريق أو من خلال جهاز محمول. </p>\r\n<h3 style=\"margin: 30px 0;\">تقنيات التتبع وملفات تعريف الارتباط </h3>\r\n<p> نستخدم ملفات تعريف الارتباط وتقنيات التتبع المماثلة لتتبع النشاط على خدمتنا وتخزين معلومات معينة. تقنيات التتبع المستخدمة هي إشارات وعلامات ونصوص لجمع المعلومات وتتبعها ولتحسين خدمتنا وتحليلها. قد تشمل التقنيات التي نستخدمها ما يلي : </p>\r\n<p> <strong> ملفات تعريف الارتباط أو ملفات تعريف ارتباط المتصفح. </strong> ملف تعريف الارتباط هو ملف صغير يوضع على جهازك. يمكنك توجيه متصفحك لرفض جميع ملفات تعريف الارتباط أو للإشارة إلى وقت إرسال ملف تعريف الارتباط. ومع ذلك ، إذا كنت لا تقبل ملفات تعريف الارتباط ، فقد لا تتمكن من استخدام بعض أجزاء من خدمتنا. ما لم تقم بتعديل إعدادات المستعرض الخاص بك بحيث يرفض ملفات تعريف الارتباط ، فقد تستخدم خدمتنا ملفات تعريف الارتباط. </p>\r\n<p> <strong> إشارات الويب. </strong> قد تحتوي أقسام معينة من خدمتنا ورسائل البريد الإلكتروني الخاصة بنا على أجزاء صغيرة\r\nالملفات الإلكترونية المعروفة باسم إشارات الويب (يشار إليها أيضًا باسم gifs الواضحة وعلامات البكسل وصور gif أحادية البكسل) التي تسمح للشركة ، على سبيل المثال ، بإحصاء المستخدمين الذين زاروا تلك\r\nالصفحات أو فتح بريد إلكتروني ولإحصائيات مواقع الويب الأخرى ذات الصلة (على سبيل المثال ، تسجيل شعبية قسم معين والتحقق من سلامة النظام والخادم). </p>\r\n<p> يمكن أن تكون ملفات تعريف الارتباط & quot؛ ثابتة & quot؛ أو & quot؛ جلسة & quot؛ بسكويت. تظل ملفات تعريف الارتباط الدائمة على جهاز الكمبيوتر الشخصي أو الجهاز المحمول الخاص بك عندما تكون غير متصل بالإنترنت ، بينما يتم حذف ملفات تعريف ارتباط الجلسة بمجرد إغلاق متصفح الويب الخاص بك. تعرف على المزيد حول ملفات تعريف الارتباط على مقالة <a href = \"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\"> موقع ويب سياسة الخصوصية المجانية </a>. </p>\r\n<p> نستخدم كلاً من ملفات تعريف الارتباط الخاصة بالجلسة وملفات تعريف الارتباط الدائمة للأغراض الموضحة أدناه : </p>\r\n<p> <strong> ملفات تعريف الارتباط الضرورية / الأساسية </strong> </p>\r\n<p>النوع : ملفات تعريف ارتباط الجلسة</p>\r\n<p> تحت إدارة : نحن </p>\r\n<p> الغرض : ملفات تعريف الارتباط هذه ضرورية لتزويدك بالخدمات المتاحة عبر موقع الويب ولتمكينك من استخدام بعض ميزاته. إنها تساعد على مصادقة المستخدمين ومنع الاستخدام الاحتيالي لحسابات المستخدمين. بدون ملفات تعريف الارتباط هذه ، لا يمكن توفير الخدمات التي طلبتها ، ونحن نستخدم ملفات تعريف الارتباط هذه فقط لتزويدك بهذه الخدمات. </p>\r\n<p> <strong> سياسة ملفات تعريف الارتباط / ملفات تعريف ارتباط قبول الإشعار </strong> </p>\r\n<p> النوع : ملفات تعريف الارتباط الدائمة </p> <p> يديرها: نحن </p> <p> الغرض: تحدد ملفات تعريف الارتباط هذه ما إذا كان المستخدمون قد وافقوا على استخدام ملفات تعريف الارتباط على موقع الويب. </p> <p> < strong> ملفات تعريف الارتباط الوظيفية </strong> </p> <p> النوع: ملفات تعريف الارتباط الدائمة </p> <p> يديرها: نحن </p> <p> الغرض: تسمح لنا ملفات تعريف الارتباط هذه بتذكر الخيارات التي تتخذها عندما استخدام موقع الويب ، مثل تذكر تفاصيل تسجيل الدخول أو تفضيلات اللغة. الغرض من ملفات تعريف الارتباط هذه هو تزويدك بتجربة شخصية أكثر وتجنب الاضطرار إلى إعادة إدخال تفضيلاتك في كل مرة تستخدم فيها الموقع. </p> <p> لمزيد من المعلومات حول ملفات تعريف الارتباط التي نستخدمها وخياراتك فيما يتعلق بملفات تعريف الارتباط ، يرجى زيارة سياسة ملفات تعريف الارتباط الخاصة بنا أو قسم ملفات تعريف الارتباط في سياسة الخصوصية الخاصة بنا. </p>\r\n<h1 style=\"margin: 30px 0;\"> استخدام بياناتك الشخصية </h2> <p> يجوز للشركة استخدام البيانات الشخصية للأغراض التالية: </p>\r\n<p> <strong> لتقديم خدمتنا وصيانتها </strong> ، بما في ذلك مراقبة استخدام خدمتنا. </p>\r\n<p> <strong> لإدارة حسابك : </strong> لإدارة تسجيلك كمستخدم للخدمة. يمكن أن تمنحك البيانات الشخصية التي تقدمها إمكانية الوصول إلى الوظائف المختلفة للخدمة المتاحة لك كمستخدم مسجل. </p> <p> <strong> لأداء العقد: </strong> التطوير والامتثال والتعهد من عقد شراء المنتجات أو العناصر أو الخدمات التي اشتريتها أو من أي عقد آخر معنا من خلال الخدمة. </p> <p> <strong> للاتصال بك: </strong> للاتصال بك عن طريق البريد الإلكتروني والمكالمات الهاتفية أو الرسائل النصية القصيرة أو الأشكال الأخرى المماثلة من الاتصالات الإلكترونية ، مثل توجيهات تطبيقات الهاتف المحمول فيما يتعلق بالتحديثات أو الاتصالات الإعلامية المتعلقة بالوظائف أو المنتجات أو الخدمات المتعاقد عليها ، بما في ذلك التحديثات الأمنية ، عندما تكون ضرورية أو معقولة لتنفيذها. </p> <p> < strong> لتزويدك </strong> بالأخبار والعروض الخاصة والمعلومات العامة حول السلع والخدمات والأحداث الأخرى التي نقدمها والتي تشبه تلك التي اشتريتها أو استفسرت عنها مسبقًا ما لم تكن قد اخترت عدم تلقي هذه المعلومات. </p> <p> <strong> لإدارة طلباتك: </strong> لحضور وإدارة طلباتك إلينا. </p> <p> <strong> لنقل الأعمال: </strong> قد نستخدم معلوماتك من أجل تقييم أو إجراء الاندماج أو التجريد أو إعادة الهيكلة أو إعادة التنظيم أو الحل أو غير ذلك من عمليات البيع أو النقل لبعض أو كل أصولنا ، سواء كان ذلك كمنشأة مستمرة أو كجزء من الإفلاس أو التصفية أو إجراء مشابه ، حيث تكون البيانات الشخصية التي نحتفظ بها عن يعد مستخدمو الخدمة لدينا من بين الأصول المنقولة. </p>\r\n<p> <strong> لأغراض أخرى </strong> : قد نستخدم معلوماتك لأغراض أخرى ، مثل تحليل البيانات ، وتحديد اتجاهات الاستخدام ، وتحديد فعالية حملاتنا الترويجية ولتقييم وتحسين خدماتنا ومنتجاتنا وخدماتنا وتسويقنا وتجربتك. </p>\r\n<p> قد نشارك معلوماتك الشخصية في المواقف التالية : </p>\r\n<ul style = \"margin: 30px 0\"> <li> <strong> مع مزودي الخدمة: </strong> قد نشارك معلوماتك الشخصية مع ServiceProviders لمراقبة وتحليل استخدام خدمتنا ، للاتصال بك. </ li> <li> <strong> لعمليات نقل الأعمال: </strong> يجوز لنا مشاركة أو نقل معلوماتك الشخصية المرتبطة أو أثناء المفاوضات بشأن أي دمج أو بيع أصول الشركة أو التمويل أو الاستحواذ على كل أو جزء من شركة أخرى. </ li> <li> <strong> مع الشركات التابعة: </strong> قد نشارك معلوماتك مع الشركات التابعة لنا ، وفي هذه الحالة سنطلب من تلك الشركات التابعة احترام سياسة الخصوصية هذه. تشمل الشركات التابعة شركتنا الأم وأي شركات فرعية أخرى أو شركاء في المشاريع المشتركة أو شركات أخرى تتحكم فيها أو تخضع لسيطرة مشتركة معنا. </ li> <li> <strong> مع شركاء الأعمال: </strong> يجوز لنا مشاركة معلوماتك مع يقدم شركاء الأعمال لدينا منتجات أو خدمات أو عروض ترويجية معينة لك. </ li> <li> <strong> مع مستخدمين آخرين: </strong> عندما تشارك معلومات شخصية أو تتفاعل بطريقة أخرى في الأماكن العامة مع مستخدمين آخرين ، يمكن عرض هذه المعلومات من قبل جميع المستخدمين ويجوز توزيعها علنًا بالخارج. </ li> <li> <strong> بموافقتك </strong>: يجوز لنا الكشف عن معلوماتك الشخصية لأي غرض آخر بموافقتك. </ li> </ul>\r\n<h2 style=\"margin: 30px 0;\"> الاحتفاظ ببياناتك الشخصية </h2>\r\n<p> ستحتفظ الشركة ببياناتك الشخصية فقط طالما كان ذلك ضروريًا للأغراض المحددة\r\nفي سياسة الخصوصية هذه. سنحتفظ ببياناتك الشخصية ونستخدمها بالقدر اللازم للامتثال\r\nمع التزاماتنا القانونية (على سبيل المثال ، إذا طُلب منا الاحتفاظ ببياناتك للامتثال لها\r\nالقوانين المعمول بها) وحل النزاعات وفرض اتفاقياتنا وسياساتنا القانونية. </p>\r\n<p> ستحتفظ الشركة أيضًا ببيانات الاستخدام لأغراض التحليل الداخلي. بشكل عام ، يتم الاحتفاظ ببيانات الاستخدام لفترة زمنية أقصر ، إلا في حالة استخدام هذه البيانات لتعزيز الأمن أو لتحسين وظائف خدمتنا ، أو نحن ملزمون قانونًا بالاحتفاظ بهذه البيانات لفترات زمنية أطول. </p>\r\n<h2 style=\"margin: 30px 0;\"> نقل بياناتك الشخصية </h2>\r\n<p> تتم معالجة معلوماتك ، بما في ذلك البيانات الشخصية ، في مكاتب تشغيل الشركة وفي أي أماكن أخرى توجد بها الأطراف المشاركة في المعالجة. هذا يعني أن هذا\r\nقد يتم نقل المعلومات إلى - والاحتفاظ بها - لأجهزة الكمبيوتر الموجودة خارج ولايتك أو مقاطعتك أو بلدك أو أي سلطة قضائية حكومية أخرى حيث قد تختلف قوانين حماية البيانات عن تلك الموجودة في ولايتك القضائية. </p>\r\n<p> موافقتك على سياسة الخصوصية هذه متبوعة بتقديمك لهذه المعلومات يمثل موافقتك على هذا النقل. </p>\r\n<p> ستتخذ الشركة جميع الخطوات اللازمة بشكل معقول لضمان التعامل مع بياناتك بشكل آمن ووفقًا لسياسة الخصوصية هذه ولن يتم نقل بياناتك الشخصية إلى منظمة أو دولة ما لم تكن هناك ضوابط كافية مطبقة بما في ذلك أمان بياناتك والمعلومات الشخصية الأخرى. </p>\r\n<h2 style=\"margin: 30px 0;\"> حذف بياناتك الشخصية </h2>\r\n<p> لديك الحق في حذف أو طلب مساعدتنا في حذف البيانات الشخصية التي جمعناها عنك. </p>\r\n<p> قد تمنحك خدمتنا القدرة على حذف معلومات معينة عنك من داخل الخدمة. </p>\r\n<p> يمكنك تحديث معلوماتك أو تعديلها أو حذفها في أي وقت عن طريق تسجيل الدخول إلى حسابك ، إذا كان لديك حساب ، وزيارة قسم إعدادات الحساب الذي يسمح لك بإدارة معلوماتك الشخصية. يمكنك أيضًا الاتصال بنا لطلب الوصول إلى أي معلومات شخصية قدمتها لنا أو تصحيحها أو حذفها. </p>\r\n<p> ومع ذلك ، يرجى ملاحظة أننا قد نحتاج إلى الاحتفاظ بمعلومات معينة عندما يكون لدينا التزام قانوني أو أساس قانوني للقيام بذلك. </p>\r\n<h2 style=\"margin: 30px 0;\"> الكشف عن بياناتك الشخصية </h2>\r\n<h3 style=\"margin: 30px 0;\">المعاملات التجارية </h3>\r\n<p> إذا كانت الشركة متورطة في عملية دمج أو استحواذ أو بيع أصول ، فقد يتم نقل بياناتك الشخصية. سنقدم إشعارًا قبل نقل بياناتك الشخصية وخضوعها لسياسة خصوصية مختلفة. </p>\r\n<h3 style=\"margin: 30px 0;\">تطبيق القانون </h3>\r\n<p> في ظل ظروف معينة ، قد يُطلب من الشركة الكشف عن بياناتك الشخصية إذا طُلب منها ذلك بموجب القانون أو استجابة لطلبات صحيحة من قبل السلطات العامة (مثل محكمة أو وكالة حكومية). </p>\r\n<h3 style=\"margin: 30px 0;\">متطلبات قانونية أخرى </h3>\r\n<p> قد تفصح الشركة عن بياناتك الشخصية بحسن نية أن هذا الإجراء ضروري من أجل : </p>\r\n<ul> <li> الامتثال لالتزام قانوني </ li> <li> حماية حقوق أو ممتلكات الشركة والدفاع عنها </ li> <li> منع المخالفات المحتملة المتعلقة بالخدمة أو التحقيق فيها </ li> < li> حماية السلامة الشخصية لمستخدمي الخدمة أو الجمهور </ li> <li> الحماية من المسؤولية القانونية </ li> </ul>\r\n<h2> أمان بياناتك الشخصية </h2>\r\n<p> يعد أمان بياناتك الشخصية أمرًا مهمًا بالنسبة لنا ، ولكن تذكر أنه لا توجد طريقة نقل عبر الإنترنت أو طريقة تخزين إلكتروني آمنة بنسبة 100٪. بينما نسعى جاهدين لاستخدام وسائل مقبولة تجاريًا لحماية بياناتك الشخصية ، لا يمكننا ضمان أمنها المطلق. </p>\r\n<h1> خصوصية الأطفال </h1>\r\n<p> لا تخاطب خدمتنا أي شخص يقل عمره عن 13 عامًا. نحن لا نجمع عن قصد معلومات تعريف شخصية من أي شخص يقل عمره عن 13 عامًا. إذا كنت أحد الوالدين أو الوصي وتدرك أن طفلك قد زودنا ببيانات شخصية ، الرجاء التواصل معنا. إذا علمنا أننا قد جمعنا بيانات شخصية من أي شخص يقل عمره عن 13 عامًا دون التحقق من موافقة الوالدين ، فإننا نتخذ خطوات لإزالة هذه المعلومات من خوادمنا. </p>\r\n<p> إذا احتجنا إلى الاعتماد على الموافقة كأساس قانوني لمعالجة معلوماتك وكان بلدك يتطلب موافقة أحد الوالدين ، فقد نطلب موافقة والديك قبل أن نجمع هذه المعلومات ونستخدمها. </p>\r\n<h1 style=\"margin: 30px 0;\">  روابط لمواقع أخرى </h1>\r\n<p> قد تحتوي خدمتنا على روابط لمواقع أخرى لا نقوم بتشغيلها. إذا قمت بالنقر فوق ارتباط جهة خارجية ، فسيتم توجيهك إلى موقع هذا الطرف الثالث. ننصحك بشدة بمراجعة سياسة الخصوصية لكل موقع تزوره. </p>\r\n<p> ليس لدينا أي سيطرة ولا نتحمل أي مسؤولية عن المحتوى أو سياسات الخصوصية أو الممارسات الخاصة بأي مواقع أو خدمات تابعة لجهات خارجية. </p>\r\n<h1 style=\"margin: 30px 0;\">  التغييرات في سياسة الخصوصية هذه </h1>\r\n<p> قد نقوم بتحديث سياسة الخصوصية الخاصة بنا من وقت لآخر. سنخطرك بأي تغييرات عن طريق نشر سياسة الخصوصية الجديدة على هذه الصفحة. </p>\r\n<p> سنخبرك عبر البريد الإلكتروني و / أو إشعارًا بارزًا على \"خدمتنا\" ، قبل أن يصبح التغيير ساريًا ونقوم بتحديث & quot؛ آخر تحديث & quot؛ التاريخ في الجزء العلوي من سياسة الخصوصية هذه. </p>\r\n<p> يُنصح بمراجعة سياسة الخصوصية هذه بشكل دوري لمعرفة أي تغييرات. تسري التغييرات التي تطرأ على سياسة الخصوصية هذه عند نشرها على هذه الصفحة. </p>\r\n<h1 style=\"margin: 30px 0;\"> اتصل بنا </h1>\r\n<p> إذا كان لديك أي أسئلة حول سياسة الخصوصية هذه ، يمكنك الاتصال بنا : </p>\r\n<ul style = \"margin: 30px 0\"> <li> من خلال زيارة هذه الصفحة على موقعنا على الويب: <a href = \"https://ishop.cholobangla.com/\" rel = \"external nofollow noopener\" target = \"_ blank \"> https://ishop.cholobangla.com/ </a> </li> </ul>\r\n<p> تم إنشاؤه باستخدام <a href = \"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\"target=\"_blank\"> منشئ سياسة الخصوصية المجاني </a> </p>\r\n\r\n','Ishop - يساعد','يساعد','ar',6,'يساعد');
