INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (15,'2024-11-19 05:44:41','2024-11-21 17:35:15','À propos','<h1 style=\"margin : 30px 0 ;\">À propos de nous</h1>\r\n<h2 style=\"margin : 30px 0 ;\">Définitions</h2>\r\n<p><strong>Compte</strong> désigne un compte unique créé pour vous permettre d\'accéder à notre Service ou à des parties de notre Service.</p>\r\n<p><strong>Entreprise</strong> (ci-après dénommée \"l\'Entreprise\", \"Nous\", \"Nous\" ou \"Notre\" dans le présent Contrat) fait référence à ishop.cholobangla.com, Canada. <</p>\r\n<p><strong>Les cookies</strong> sont de petits fichiers qui sont placés sur votre ordinateur, appareil mobile ou tout autre appareil par un site Web, contenant les détails de votre historique de navigation sur ce site Web parmi ses nombreuses utilisations.</p>\r\n<p><strong>Pays</strong> désigne : Nouveau-Brunswick, Canada</p>\r\n<p><strong>Appareil</strong> désigne tout appareil pouvant accéder au Service tel qu\'un ordinateur, un téléphone portable ou une tablette numérique.</p>\r\n<p><strong>Les données personnelles</strong> sont toutes les informations relatives à une personne identifiée ou identifiable.</p>\r\n<p><strong>Service</strong> fait référence au site Web.</p>\r\n<p><strong>Prestataire de services</strong> désigne toute personne physique ou morale qui traite les données pour le compte de la Société. Il fait référence à des sociétés tierces ou à des personnes employées par la Société pour faciliter le Service, pour fournir le Service au nom de la Société, pour fournir des services liés au Service ou pour aider la Société à analyser la manière dont le Service est utilisé.</p>\r\n<p><strong>Les données d\'utilisation</strong> font référence aux données collectées automatiquement, soit générées par l\'utilisation du Service, soit à partir de l\'infrastructure du Service elle-même (par exemple, la durée de la visite d\'une page).</p>\r\n<p><strong>Site Web</strong> fait référence à https://www.ishop.cholobangla.com/, accessible depuis <a href=\"ishop.com\" rel=\"external nofollow noopener\" target=\"_blank\"> ishop.cholobangla.com</a></p>\r\n<p><strong>Vous</strong> désigne la personne accédant ou utilisant le Service, ou la société ou toute autre entité juridique au nom de laquelle cette personne accède ou utilise le Service, selon le cas.</p>\r\n','Ishop - À propos','À propos','fr',1,'À,propos');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (16,'2024-11-19 05:44:41','2024-11-21 17:35:15','FAQ','<h1 style=\"margin: 30px 0;\">Questions fréquentes</h1>\r\n<h2 style=\"margin: 30px 0;\">Aperçu?</h2>\r\n<p>ishop est un CMS de commerce électronique multi-fournisseurs. L\'API est construite avec <b>laravel</b>, le panneau d\'administration et le front-end est construit avec <strong>nuxt js</strong>.Pour stocker des données <b>mysql </b> est utilisé. Les performances du site sont super rapides grâce au système de <b>cache</b> avancé. Il est entièrement réactif et hautement personnalisable. Dans le panneau d\'administration de licence standard, les fichiers de construction ne seront pas trouvés, cela signifie que vous ne pourrez pas personnaliser la conception du panneau d\'administration. Le code source de l\'interface et de l\'API se trouve dans le dossier du package. Vous pouvez très facilement personnaliser l\'interface et l\'API selon vos besoins. Le code source du panneau d\'administration se trouve dans la licence étendue. Pour toute question, veuillez contacter notre équipe d\'assistance à <a href=\"mailto:iyozedcontact@gmail.com\" class=\"link\"><b>iyozedcontact@gmail.com</b></a></p>\r\n<h2 style=\"margin: 30px 0;\">Fournissons-nous une assistance à l\'installation pour les utilisateurs?</h2>\r\n<p>Oui, nous fournissons une assistance à l\'installation aux utilisateurs. N\'hésitez pas à nous envoyer un e-mail à tout moment.</p>\r\n<h2 style=\"margin: 30px 0;\">Fournissons-nous un guide d\'installation aux utilisateurs?</h2>\r\n<p>Oui, nous fournissons un guide d\'installation aux utilisateurs avec les packages.</p>\r\n<h2 style=\"margin: 30px 0;\">Combien de temps faut-il pour revenir à l\'utilisateur?</h2>\r\n<p>Nous répondons aux utilisateurs dès que possible.</p>\r\n','Ishop - FAQ','FAQ','fr',2,'FAQ');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (17,'2024-11-19 05:44:41','2024-11-21 17:35:15','Contact','Contact','Ishop - Contact','Contact','fr',3,'Contact');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (18,'2024-11-19 05:44:41','2024-11-21 17:35:15','Politique de remboursement','<h1 style= \"margin: 30px 0;\">Politique de remboursement</h1>\r\n<h2 style= \"margin: 30px 0;\">Définitions</h2>\r\n<p>Aux fins de la présente politique de confidentialité: </p>\r\n<p><strong>Compte</strong> désigne un compte unique créé pour vous permettre d\'accéder à notre Service ou à des parties de notre Service.</p>\r\n<p><strong>Société</strong> (ci-après dénommée «la Société», «Nous», «Nous» ou «Notre» dans le présent Accord) fait référence à ishop.cholobangla.com, Canada. </p>\r\n<p><strong>Les cookies</strong> sont de petits fichiers qui sont placés sur votre ordinateur, appareil mobile ou tout autre appareil par un site Web, contenant les détails de votre historique de navigation sur ce site Web parmi ses nombreuses utilisations.</p>\r\n<p><strong>Pays</strong> désigne: Nouveau-Brunswick, Canada</p>\r\n<p><strong>Appareil</strong> désigne tout appareil pouvant accéder au Service tel qu\'un ordinateur, un téléphone portable ou une tablette numérique.</p>\r\n<p><strong>Les données personnelles</strong> sont toutes les informations relatives à une personne identifiée ou identifiable.</p>\r\n<p><strong>Service</strong> fait référence au site Web.</p>\r\n<p><strong>Prestataire de services</strong> désigne toute personne physique ou morale qui traite les données pour le compte de la Société. Il fait référence à des sociétés tierces ou à des personnes employées par la Société pour faciliter le Service, pour fournir le Service au nom de la Société, pour effectuer des services liés au Service ou pour aider la Société à analyser la manière dont le Service est utilisé.</p>\r\n<p><strong>Données d\'utilisation</strong> fait référence aux données collectées automatiquement, soit générées par l\'utilisation du Service, soit à partir de l\'infrastructure du Service elle-même (par exemple, la durée d\'une visite de page).</p>\r\n<p><strong>Site Web</strong> fait référence à https: //ishop.cholobangla.com/, accessible depuis <a href=\"ishop.cholobangla.com\" rel=\"external nofollow noopener\" target=\"_blank\"> ishop.cholobangla.com</a></p>\r\n<p><strong>Vous</strong> désigne la personne accédant ou utilisant le Service, ou la société ou toute autre entité juridique au nom de laquelle cette personne accède ou utilise le Service, selon le cas.</p>\r\n<h1 style= \"margin: 30px 0;\">Collecte et utilisation de vos données personnelles</h1>\r\n<h2 style= \"margin: 30px 0;\">Types de données collectées</h2>\r\n<h3 style= \"margin: 30px 0;\">Données personnelles</h3>\r\n<p>Lorsque vous utilisez Notre Service, Nous pouvons Vous demander de Nous fournir certaines informations personnellement identifiables qui peuvent être utilisées pour Vous contacter ou Vous identifier. Les informations personnellement identifiables peuvent inclure, mais sans s\'y limiter: </p>\r\n<ul style= \"margin: 30px 0;\"><li>Adresse e-mail</li><li>Prénom et nom</li><li>Adresse, État, Province, Code postal/ZIP, Ville</ li><li>Données d\'utilisation</li></ul>\r\n<h3 style= \"margin: 30px 0;\">Données d\'utilisation</h3>\r\n<p>Les données d\'utilisation sont collectées automatiquement lors de l\'utilisation du service.</p>\r\n<p>Les données d\'utilisation peuvent inclure des informations telles que l\'adresse de protocole Internet de votre appareil (par exemple, l\'adresse IP), le type de navigateur, la version du navigateur, les pages de notre service que vous visitez, l\'heure et la date de votre visite, le temps passé sur ces pages , des identifiants d\'appareil uniques et d\'autres données de diagnostic.</p>\r\n<p>Lorsque vous accédez au Service par ou via un appareil mobile, nous pouvons collecter certaines informations automatiquement, y compris, mais sans s\'y limiter, le type d\'appareil mobile que vous utilisez, l\'identifiant unique de votre appareil mobile, l\'adresse IP de votre appareil mobile , votre système d\'exploitation mobile, le type de navigateur Internet mobile que vous utilisez, les identifiants uniques de l\'appareil et d\'autres données de diagnostic.</p>\r\n<p>Nous pouvons également collecter des informations que votre navigateur envoie chaque fois que vous visitez notre service ou lorsque vous accédez au service par ou via un appareil mobile.</p>\r\n<h3 style= \"margin: 30px 0;\">Technologies de suivi et cookies</h3>\r\n<p>Nous utilisons des cookies et des technologies de suivi similaires pour suivre l\'activité sur notre service et stocker certaines informations. Les technologies de suivi utilisées sont des balises, des balises et des scripts pour collecter et suivre les informations et pour améliorer et analyser notre service. Les technologies que nous utilisons peuvent inclure : </p>\r\n<ul style= \"margin: 30px 0;\"><li><strong>Cookies ou cookies de navigateur.</strong> Un cookie est un petit fichier placé sur votre appareil. Vous pouvez demander à Votre navigateur de refuser tous les Cookies ou de vous signaler l\'envoi d\'un Cookie. Cependant, si vous n\'acceptez pas les cookies, vous ne pourrez peut-être pas utiliser certaines parties de notre service. À moins que vous n\'ayez réglé les paramètres de votre navigateur de manière à ce qu\'il refuse les cookies, notre service peut utiliser des cookies.</li><li><strong>Balises Web.</strong> Certaines sections de notre service et nos e-mails peuvent contenir de petits fichiers électroniques connues sous le nom de balises Web (également appelées gifs clairs, pixels invisibles et gifs à pixel unique) qui permettent à la Société, par exemple, de compter les utilisateurs qui ont visité ces pages ou ouvert un e-mail et pour d\'autres statistiques de sites Web connexes (par exemple , enregistrant la popularité d\'une certaine section et vérifiant l\'intégrité du système et du serveur).</li></ul>\r\n<p>Les cookies peuvent être &quot;Persistants&quot; ou &quot;Session&quot; Biscuits. Les cookies persistants restent sur votre ordinateur personnel ou votre appareil mobile lorsque vous vous déconnectez, tandis que les cookies de session sont supprimés dès que vous fermez votre navigateur Web. Pour en savoir plus sur les cookies, consultez l\'article du <a href= \"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\"> site Web sur la politique de confidentialité gratuite</a>. </p>\r\n<p>Nous utilisons à la fois des cookies de session et des cookies persistants aux fins décrites ci-dessous: </p>\r\n<p><strong>Cookies nécessaires/essentiels</strong></p>\r\n<p>Type: Cookies de session</p>\r\n<p>Géré par: Nous</p>\r\n<p>Objectif: Ces cookies sont essentiels pour vous fournir les services disponibles via le site Web et pour vous permettre d\'utiliser certaines de ses fonctionnalités. Ils aident à authentifier les utilisateurs et à empêcher l\'utilisation frauduleuse des comptes d\'utilisateurs. Sans ces cookies, les services que vous avez demandés ne peuvent pas être fournis, et nous n\'utilisons ces cookies que pour vous fournir ces services.</p>\r\n<p><strong>Politique relative aux cookies / Avis d\'acceptation des cookies</strong></p>\r\n<p>Type: Cookies persistants</p>\r\n<p>Géré par: Nous</p>\r\n<p>Objectif: Ces cookies identifient si les utilisateurs ont accepté l\'utilisation de cookies sur le site Web.</p>\r\n<p><strong>Cookies de fonctionnalité</strong></p>\r\n<p>Type: Cookies persistants</p>\r\n<p>Géré par: Nous</p>\r\n<p>Objectif: ces cookies nous permettent de mémoriser les choix que vous faites lorsque vous utilisez le site Web, tels que la mémorisation de vos informations de connexion ou de votre préférence de langue. Le but de ces Cookies est de Vous offrir une expérience plus personnelle et de Vous éviter d\'avoir à ressaisir vos préférences à chaque fois que Vous utilisez le Site.</p>\r\n<p>Pour plus d\'informations sur les cookies que nous utilisons et vos choix concernant les cookies, veuillez consulter notre Politique relative aux cookies ou la section Cookies de notre Politique de confidentialité.</p>\r\n<h2 style= \"margin: 30px 0;\">Utilisation de vos données personnelles</h2>\r\n<p>La Société peut utiliser les Données personnelles aux fins suivantes: </p>\r\n<p><strong>Pour fournir et maintenir notre Service</strong>, y compris pour surveiller l\'utilisation de notre Service.</p>\r\n<p><strong>Pour gérer Votre Compte: </strong> pour gérer Votre inscription en tant qu\'utilisateur du Service. Les données personnelles que vous fournissez peuvent vous donner accès à différentes fonctionnalités du service qui sont à votre disposition en tant qu\'utilisateur enregistré.</p>\r\n<p><strong>Pour l\'exécution d\'un contrat: </strong> l\'élaboration, le respect et l\'engagement du contrat d\'achat des produits, articles ou services que vous avez achetés ou de tout autre contrat avec nous via le service.</p>\r\n<p><strong>Pour vous contacter: </strong> pour vous contacter par e-mail, appels téléphoniques, SMS ou autres formes de communication électronique équivalentes, telles que les notifications push d\'une application mobile concernant les mises à jour ou les communications informatives liées aux fonctionnalités, produits ou services sous-traités, y compris les mises à jour de sécurité, lorsque cela est nécessaire ou raisonnable pour leur mise en œuvre.</p>\r\n<p><strong>Pour vous fournir</strong> des actualités, des offres spéciales et des informations générales sur d\'autres biens, services et événements que nous proposons et qui sont similaires à ceux que vous avez déjà achetés ou sur lesquels vous vous êtes renseigné, sauf si vous avez choisi de ne pas le faire recevoir ces informations.</p>\r\n<p><strong>Pour gérer vos demandes: </strong> pour assister et gérer vos demandes que vous nous adressez.</p>\r\n<p><strong>Pour les transferts d\'entreprise: </strong> Nous pouvons utiliser Vos informations pour évaluer ou mener une fusion, une cession, une restructuration, une réorganisation, une dissolution ou toute autre vente ou transfert de tout ou partie de Nos actifs, que ce soit en tant que en cours d\'exploitation ou dans le cadre d\'une faillite, d\'une liquidation ou d\'une procédure similaire, dans laquelle les données personnelles que nous détenons sur les utilisateurs de nos services font partie des actifs transférés.</p>\r\n<p><strong>À d\'autres fins</strong>: nous pouvons utiliser vos informations à d\'autres fins, telles que l\'analyse de données, l\'identification des tendances d\'utilisation, la détermination de l\'efficacité de nos campagnes promotionnelles et pour évaluer et améliorer notre service, nos produits, nos services , le marketing et votre expérience.</p>\r\n\r\n','Ishop - Politique de remboursement','Politique de remboursement','fr',4,'Politique,de,remboursement');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (19,'2024-11-19 05:44:41','2024-11-21 17:35:15','politique de confidentialité','<h1 style = \"margin: 30px 0;\">Politique de confidentialité</h1>\r\n<p>Dernière mise à jour: 13 décembre 2022</p>\r\n<p>Cette politique de confidentialité décrit nos politiques et procédures sur la collecte, l\'utilisation et la divulgation de vos informations lorsque vous utilisez le service et vous informe sur vos droits en matière de confidentialité et sur la manière dont la loi vous protège.</p>\r\n<p>Nous utilisons vos données personnelles pour fournir et améliorer le service. En utilisant le Service, Vous acceptez la collecte et l\'utilisation d\'informations conformément à la présente Politique de confidentialité. Cette politique de confidentialité a été créée à l\'aide du <a href = \"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\" target=\"_blank\"> Générateur gratuit de politique de confidentialité</a>. </p>\r\n<h1 style = \"margin: 30px 0;\">Interprétation et définitions</h1>\r\n<h2 style = \"margin: 30px 0;\">Interprétation</h2>\r\n<p>Les mots dont la lettre initiale est en majuscule ont des significations définies dans les conditions suivantes. Les définitions suivantes auront la même signification, qu\'elles apparaissent au singulier ou au pluriel.</p>\r\n<h2 style = \"margin: 30px 0;\">Définitions</h2>\r\n<p>Aux fins de la présente politique de confidentialité: </p>\r\n<strong>Compte</strong> désigne un compte unique créé pour vous permettre d\'accéder à notre service ou à des parties de notre service.</p>\r\n<p><strong>Société</strong> (ci-après dénommée «la Société», «Nous», «Nous» ou «Notre» dans le présent Accord) fait référence à ishop.cholobangla.com, Canada. </p>\r\n<p><strong>Les cookies</strong> sont de petits fichiers qui sont placés sur votre ordinateur, appareil mobile ou tout autre appareil par un site Web, contenant les détails de votre historique de navigation sur ce site Web parmi ses nombreuses utilisations.</p>\r\n<p><strong>Pays</strong> fait référence à: Nouveau-Brunswick, Canada</p>\r\n<p><strong>Appareil</strong> désigne tout appareil pouvant accéder au Service tel qu\'un ordinateur, un téléphone portable ou une tablette numérique.</p>\r\n<p><strong>Les données personnelles</strong> sont toutes les informations relatives à une personne identifiée ou identifiable.</p>\r\n<p><strong>Service</strong> fait référence au site Web.</p>\r\n<p><strong>Prestataire de services</strong> désigne toute personne physique ou morale qui traite les données pour le compte de la Société. Il fait référence à des sociétés tierces ou à des personnes employées par la Société pour faciliter le Service, pour fournir le Service au nom de la Société, pour effectuer des services liés au Service ou pour aider la Société à analyser la manière dont le Service est utilisé.</p>\r\n<p><strong>Données d\'utilisation</strong> fait référence aux données collectées automatiquement, soit générées par l\'utilisation du Service, soit à partir de l\'infrastructure du Service elle-même (par exemple, la durée d\'une visite de page).</p>\r\n<p><strong>Site Web</strong> fait référence à https: //ishop.cholobangla.com/, accessible depuis <a href=\"ishop.cholobangla.com\" rel=\"external nofollow noopener\" target=\"_blank\"> ishop.cholobangla.com</a></p>\r\n<p><strong>Vous</strong> désigne la personne accédant ou utilisant le Service, ou la société ou toute autre entité juridique au nom de laquelle cette personne accède ou utilise le Service, selon le cas.</p>\r\n<h1 style = \"margin: 30px 0;\">Collecte et utilisation de vos données personnelles</h1>\r\n<h2 style = \"margin: 30px 0;\">Types de données collectées</h2>\r\n<h3 style = \"margin: 30px 0;\">Données personnelles</h3>\r\n<p>Lorsque vous utilisez Notre Service, Nous pouvons Vous demander de Nous fournir certaines informations personnellement identifiables qui peuvent être utilisées pour Vous contacter ou Vous identifier. Les informations personnellement identifiables peuvent inclure, mais sans s\'y limiter: </p>\r\n<ul style = \"margin: 30px 0;\"><li>Adresse e-mail</li><li>Prénom et nom</li><li>Adresse, État, Province, Code postal/ZIP, Ville</ li><li>Données d\'utilisation</li></ul>\r\n<h3 style = \"margin: 30px 0;\">Données d\'utilisation</h3>\r\n<p>Les données d\'utilisation sont collectées automatiquement lors de l\'utilisation du service.</p>\r\n<p>Les données d\'utilisation peuvent inclure des informations telles que l\'adresse de protocole Internet de votre appareil (par exemple, l\'adresse IP), le type de navigateur, la version du navigateur, les pages de notre service que vous visitez, l\'heure et la date de votre visite, le temps passé sur ces pages , des identifiants d\'appareil uniques et d\'autres données de diagnostic.</p>\r\n<p>Lorsque vous accédez au Service par ou via un appareil mobile, nous pouvons collecter certaines informations automatiquement, y compris, mais sans s\'y limiter, le type d\'appareil mobile que vous utilisez, l\'identifiant unique de votre appareil mobile, l\'adresse IP de votre appareil mobile , votre système d\'exploitation mobile, le type de navigateur Internet mobile que vous utilisez, les identifiants uniques de l\'appareil et d\'autres données de diagnostic.</p>\r\n<p>Nous pouvons également collecter des informations que votre navigateur envoie chaque fois que vous visitez notre service ou lorsque vous accédez au service par ou via un appareil mobile.</p>\r\n<h3 style = \"margin: 30px 0;\">Technologies de suivi et cookies</h3>\r\n<p>Nous utilisons des cookies et des technologies de suivi similaires pour suivre l\'activité sur notre service et stocker certaines informations. Les technologies de suivi utilisées sont des balises, des balises et des scripts pour collecter et suivre les informations et pour améliorer et analyser notre service. Les technologies que Nous utilisons peuvent inclure : </p>\r\n<p><strong>Cookies ou cookies de navigateur.</strong> Un cookie est un petit fichier placé sur votre appareil. Vous pouvez demander à Votre navigateur de refuser tous les Cookies ou de vous signaler l\'envoi d\'un Cookie. Cependant, si vous n\'acceptez pas les cookies, vous ne pourrez peut-être pas utiliser certaines parties de notre service. À moins que vous n\'ayez réglé les paramètres de votre navigateur pour qu\'il refuse les cookies, notre service peut utiliser des cookies.</p>\r\n<p><strong>Balises Web.</strong> Certaines sections de notre Service et de nos e-mails peuvent contenir de petits fichiers électroniques connus sous le nom de balises Web (également appelés gifs transparents, pixels invisibles et gifs à pixel unique) qui permettent à la Société, par exemple, pour compter les utilisateurs qui ont visité ces pages ou ouvert un e-mail et pour d\'autres statistiques de site Web connexes (par exemple, enregistrer la popularité d\'une certaine section et vérifier l\'intégrité du système et du serveur).</p>\r\n<p>Les cookies peuvent être &quot;Persistants&quot; ou &quot;Session&quot; Biscuits. Les cookies persistants restent sur votre ordinateur personnel ou votre appareil mobile lorsque vous vous déconnectez, tandis que les cookies de session sont supprimés dès que vous fermez votre navigateur Web. Pour en savoir plus sur les cookies, consultez l\'article du <a href = \"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\"> site Web sur la politique de confidentialité gratuite</a>. </p>\r\n<p>Nous utilisons à la fois des cookies de session et des cookies persistants aux fins décrites ci-dessous: </p>\r\n<p><strong>Cookies nécessaires/essentiels</strong></p>\r\n<p>Type: Cookies de session</p>\r\n<p>Géré par : Nous</p>\r\n<p>Objectif: Ces cookies sont essentiels pour vous fournir les services disponibles via le site Web et pour vous permettre d\'utiliser certaines de ses fonctionnalités. Ils aident à authentifier les utilisateurs et à empêcher l\'utilisation frauduleuse des comptes d\'utilisateurs. Sans ces cookies, les services que vous avez demandés ne peuvent pas être fournis, et nous n\'utilisons ces cookies que pour vous fournir ces services.</p>\r\n<p><strong>Politique relative aux cookies / Avis d\'acceptation des cookies</strong></p>\r\n<p>Type: Cookies persistants</p>\r\n<p>Géré par : Nous</p>\r\n<p>Objectif: Ces cookies identifient si les utilisateurs ont accepté l\'utilisation de cookies sur le site Web.</p>\r\n<p><strong>Cookies de fonctionnalité</strong></p>\r\n<p>Type: Cookies persistants</p>\r\n<p>Géré par : Nous</p>\r\n<p>Objectif: Ces cookies nous permettent de mémoriser les choix que vous faites lorsque vous utilisez le site Web, tels que la mémorisation de vos informations de connexion ou de votre préférence de langue. Le but de ces Cookies est de Vous offrir une expérience plus personnelle et de Vous éviter d\'avoir à ressaisir vos préférences à chaque fois que Vous utilisez le Site.</p>\r\n<p>Pour plus d\'informations sur les cookies que nous utilisons et vos choix concernant les cookies, veuillez consulter notre Politique relative aux cookies ou la section Cookies de notre Politique de confidentialité.</p>\r\n<h2 style = \"margin: 30px 0;\">Utilisation de vos données personnelles</h2>\r\n<p>La Société peut utiliser les Données Personnelles aux fins suivantes: </p>\r\n<p><strong>Pour fournir et maintenir notre Service</strong>, y compris pour surveiller l\'utilisation de notre Service.</p>\r\n<p><strong>Pour gérer Votre Compte : </strong> pour gérer Votre inscription en tant qu\'utilisateur du Service. Les données personnelles que vous fournissez peuvent vous donner accès à différentes fonctionnalités du service qui sont à votre disposition en tant qu\'utilisateur enregistré.</p>\r\n<p><strong>Pour l\'exécution d\'un contrat: </strong> l\'élaboration, le respect et l\'exécution du contrat d\'achat des produits, articles ou services que vous avez achetés ou de tout autre contrat avec nous par le biais du service.</p>\r\n<p><strong>Pour vous contacter: </strong> pour vous contacter par e-mail, appels téléphoniques, SMS ou autres formes de communication électronique équivalentes, telles que les notifications push d\'une application mobile concernant les mises à jour ou les communications informatives liées aux fonctionnalités, produits ou services sous-traités, y compris les mises à jour de sécurité, lorsque cela est nécessaire ou raisonnable pour leur mise en œuvre.</p>\r\n<p><strong>Pour vous fournir</strong> des actualités, des offres spéciales et des informations générales sur d\'autres biens, services et événements que nous proposons et qui sont similaires à ceux que vous avez déjà achetés ou sur lesquels vous vous êtes renseigné, sauf si vous avez choisi de ne pas le faire recevoir ces informations.</p>\r\n<p><strong>Pour gérer Vos demandes: </strong> Pour assister et gérer Vos demandes envers Nous.</p>\r\n<p><strong>Pour les transferts d\'entreprise: </strong> Nous pouvons utiliser Vos informations pour évaluer ou mener une fusion, une cession, une restructuration, une réorganisation, une dissolution ou toute autre vente ou transfert de tout ou partie de Nos actifs, que ce soit en tant que en cours d\'exploitation ou dans le cadre d\'une faillite, d\'une liquidation ou d\'une procédure similaire, dans laquelle les données personnelles que nous détenons sur les utilisateurs de nos services font partie des actifs transférés.</p>\r\n<p><strong>À d\'autres fins</strong>: nous pouvons utiliser vos informations à d\'autres fins, telles que l\'analyse de données, l\'identification des tendances d\'utilisation, la détermination de l\'efficacité de nos campagnes promotionnelles et pour évaluer et améliorer notre service, nos produits, nos services , le marketing et votre expérience.</p>\r\n<p>Nous pouvons partager Vos informations personnelles dans les situations suivantes: </p>\r\n<ul style = \"margin: 30px 0;\"><li><strong>Avec les fournisseurs de services:</strong> nous pouvons partager vos informations personnelles avec les fournisseurs de services pour surveiller et analyser l\'utilisation de notre service, pour vous contacter.< /li><li><strong>Pour les transferts d\'entreprise:</strong> Nous pouvons partager ou transférer vos informations personnelles dans le cadre de, ou pendant les négociations de, toute fusion, vente d\'actifs de la Société, financement ou acquisition de tout ou partie partie de nos activités à une autre société.</li><li><strong>Avec des affiliés:</strong> nous pouvons partager vos informations avec nos affiliés, auquel cas nous exigerons que ces affiliés respectent cette politique de confidentialité. Les sociétés affiliées incluent notre société mère et toutes autres filiales, partenaires de coentreprise ou autres sociétés que nous contrôlons ou qui sont sous contrôle commun avec nous.</li><li><strong>Avec des partenaires commerciaux:</strong> nous pouvons partager votre informations avec nos partenaires commerciaux pour vous proposer certains produits, services ou promotions.</li><li><strong>Avec d\'autres utilisateurs:</strong> lorsque vous partagez des informations personnelles ou interagissez autrement dans les espaces publics avec d\'autres utilisateurs, tels que les informations peuvent être vues par tous les utilisateurs et peuvent être diffusées publiquement à l\'extérieur.</li><li><strong>Avec Votre consentement</strong>: Nous pouvons divulguer Vos informations personnelles à toute autre fin avec Votre consentement.</li> </ul>\r\n<h2 style = \"margin: 30px 0;\">Conservation de vos données personnelles</h2>\r\n<p>La Société ne conservera vos données personnelles que le temps nécessaire aux fins énoncées dans la présente politique de confidentialité. Nous conserverons et utiliserons vos données personnelles dans la mesure nécessaire pour nous conformer à nos obligations légales (par exemple, si nous sommes tenus de conserver vos données pour nous conformer aux lois applicables), résoudre les litiges et appliquer nos accords et politiques juridiques.</p>\r\n<p>La Société conservera également les Données d\'utilisation à des fins d\'analyse interne. Les données d\'utilisation sont généralement conservées pendant une période plus courte, sauf lorsque ces données sont utilisées pour renforcer la sécurité ou pour améliorer la fonctionnalité de notre service, ou lorsque nous sommes légalement tenus de conserver ces données pendant des périodes plus longues.</p>\r\n<h2 style = \"margin: 30px 0;\">Transfert de vos données personnelles</h2>\r\n<p>Vos informations, y compris les données personnelles, sont traitées dans les bureaux d\'exploitation de la société et dans tout autre lieu où se trouvent les parties impliquées dans le traitement. Cela signifie que ces informations peuvent être transférées et conservées sur des ordinateurs situés en dehors de votre état, province, pays ou autre juridiction gouvernementale où les lois sur la protection des données peuvent différer de celles de votre juridiction.</p>\r\n<p>Votre consentement à cette politique de confidentialité suivi de votre soumission de ces informations représente votre accord à ce transfert.</p>\r\n<p>La Société prendra toutes les mesures raisonnablement nécessaires pour s\'assurer que Vos données sont traitées en toute sécurité et conformément à la présente Politique de confidentialité et aucun transfert de Vos Données personnelles n\'aura lieu vers une organisation ou un pays à moins que des contrôles adéquats ne soient en place, y compris la sécurité de vos données et autres informations personnelles.</p>\r\n<h2 style = \"margin: 30px 0;\">Supprimer vos données personnelles</h2>\r\n<p>Vous avez le droit de supprimer ou de demander que nous vous aidions à supprimer les données personnelles que nous avons collectées à votre sujet.</p>\r\n<p>Notre service peut vous donner la possibilité de supprimer certaines informations vous concernant depuis le service.</p>\r\n<p>Vous pouvez mettre à jour, modifier ou supprimer vos informations à tout moment en vous connectant à votre compte, si vous en avez un, et en visitant la section des paramètres du compte qui vous permet de gérer vos informations personnelles. Vous pouvez également nous contacter pour demander l\'accès, la correction ou la suppression de toute information personnelle que vous nous avez fournie.</p>\r\n<p>Veuillez noter, cependant, que nous pouvons avoir besoin de conserver certaines informations lorsque nous avons une obligation légale ou une base légale pour le faire.</p>\r\n<h2 style = \"margin: 30px 0;\">Divulgation de vos données personnelles</h2>\r\n<h3 style = \"margin: 30px 0;\">Transactions commerciales</h3>\r\n<p>Si la Société est impliquée dans une fusion, une acquisition ou une vente d\'actifs, vos données personnelles peuvent être transférées. Nous vous informerons avant que vos données personnelles ne soient transférées et soumises à une politique de confidentialité différente.</p>\r\n<h3 style = \"margin: 30px 0;\">Application de la loi</h3>\r\n<p>Dans certaines circonstances, la Société peut être tenue de divulguer vos données personnelles si la loi l\'exige ou en réponse à des demandes valables d\'autorités publiques (par exemple, un tribunal ou une agence gouvernementale).</p>\r\n<h3 style = \"margin: 30px 0;\">Autres exigences légales</h3>\r\n<p>La Société peut divulguer Vos Données Personnelles en croyant de bonne foi qu\'une telle action est nécessaire pour: </p>\r\n<ul><li>Se conformer à une obligation légale</li><li>Protéger et défendre les droits ou la propriété de la Société</li><li>Prévenir ou enquêter sur d\'éventuels actes répréhensibles en rapport avec le Service</li>< li>Protéger la sécurité personnelle des Utilisateurs du Service ou du public</li><li>Protéger contre la responsabilité légale</li></ul>\r\n<h2>Sécurité de vos données personnelles</h2>\r\n<p>La sécurité de vos données personnelles est importante pour nous, mais n\'oubliez pas qu\'aucune méthode de transmission sur Internet ou méthode de stockage électronique n\'est sécurisée à 100%. Bien que nous nous efforcions d\'utiliser des moyens commercialement acceptables pour protéger vos données personnelles, nous ne pouvons garantir leur sécurité absolue.</p>\r\n<h1>Confidentialité des enfants</h1>\r\n<p>Notre service ne s\'adresse pas aux personnes de moins de 13ans. Nous ne collectons pas sciemment d\'informations personnellement identifiables auprès de personnes de moins de 13ans. Si vous êtes un parent ou un tuteur et que vous savez que votre enfant nous a fourni des informations personnelles. Données, veuillez nous contacter. Si nous apprenons que nous avons collecté des données personnelles auprès d\'une personne de moins de 13 ans sans vérification du consentement parental, nous prenons des mesures pour supprimer ces informations de nos serveurs.</p>\r\n<p>Si nous devons compter sur le consentement comme base légale pour le traitement de vos informations et que votre pays exige le consentement d\'un parent, nous pouvons exiger le consentement de votre parent avant de collecter et d\'utiliser ces informations.</p>\r\n<h1 style = \"margin: 30px 0;\">Liens vers d\'autres sites Web</h1>\r\n<p>Notre Service peut contenir des liens vers d\'autres sites Web qui ne sont pas exploités par Nous. Si vous cliquez sur un lien tiers, vous serez dirigé vers le site de ce tiers. Nous vous conseillons vivement de consulter la politique de confidentialité de chaque site que vous visitez.</p>\r\n<p>Nous n\'avons aucun contrôle et n\'assumons aucune responsabilité quant au contenu, aux politiques de confidentialité ou aux pratiques des sites ou services tiers.</p>\r\n<h1 style = \"margin: 30px 0;\">Modifications de cette politique de confidentialité</h1>\r\n<p>Nous pouvons mettre à jour notre politique de confidentialité de temps à autre. Nous vous informerons de tout changement en publiant la nouvelle politique de confidentialité sur cette page.</p>\r\n<p>Nous vous informerons par e-mail et/ou par un avis visible sur notre service, avant que le changement ne devienne effectif et mettrons à jour la &quot;Dernière mise à jour&quot; date en haut de cette politique de confidentialité.</p>\r\n<p>Il vous est conseillé de consulter régulièrement cette politique de confidentialité pour tout changement. Les modifications apportées à cette politique de confidentialité entrent en vigueur lorsqu\'elles sont publiées sur cette page.</p>\r\n<h1 style = \"margin: 30px 0;\">Contactez-nous</h1>\r\n<p>Si vous avez des questions concernant cette politique de confidentialité, vous pouvez nous contacter: </p>\r\n<ul style = \"margin: 30px 0;\"><li>En visitant cette page sur notre site: <a href=\"https://ishop.cholobangla.com/\" rel=\"external nofollow noopener\" target=\"_blank \">https://ishop.cholobangla.com/</a></li></ul>\r\n\r\n','Ishop - politique de confidentialité','politique de confidentialité','fr',5,'politique,de,confidentialité');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (20,'2024-11-19 05:44:41','2024-11-21 17:35:15','Aider','<h1 style = \"margin: 30px 0;\">Aide</h1>\r\n<p>Cette politique de confidentialité décrit nos politiques et procédures sur la collecte, l\'utilisation et la divulgation de vos informations lorsque vous utilisez le service et vous informe sur vos droits en matière de confidentialité et sur la manière dont la loi vous protège.</p>\r\n<p>Nous utilisons vos données personnelles pour fournir et améliorer le service. En utilisant le Service, Vous acceptez la collecte et l\'utilisation d\'informations conformément à la présente Politique de confidentialité. Cette politique de confidentialité a été créée à l\'aide du <a href = \"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\" target=\"_blank\"> Générateur gratuit de politique de confidentialité</a>. </p>\r\n<h1 style = \"margin: 30px 0;\">Interprétation et définitions</h1>\r\n<h2 style = \"margin: 30px 0;\">Interprétation</h2>\r\n<p>Les mots dont la lettre initiale est en majuscule ont des significations définies dans les conditions suivantes. Les définitions suivantes auront la même signification, qu\'elles apparaissent au singulier ou au pluriel.</p>\r\n<h2 style = \"margin: 30px 0;\">Définitions</h2>\r\n<p>Aux fins de la présente politique de confidentialité: </p>\r\n<p><strong>Compte</strong> désigne un compte unique créé pour vous permettre d\'accéder à notre service ou à des parties de notre service.</p>\r\n<p><strong>Société</strong> (ci-après dénommée «la Société», «Nous», «Nous» ou «Notre» dans le présent Accord) fait référence à ishop.cholobangla.com, Canada. </p>\r\n<p><strong>Les cookies</strong> sont de petits fichiers qui sont placés sur votre ordinateur, appareil mobile ou tout autre appareil par un site Web, contenant les détails de votre historique de navigation sur ce site Web parmi ses nombreuses utilisations.</p>\r\n<p><strong>Pays</strong> fait référence à: Nouveau-Brunswick, Canada</p>\r\n<p><strong>Appareil</strong> désigne tout appareil pouvant accéder au Service, tel qu\'un ordinateur, un téléphone portable ou une tablette numérique.</p>\r\n<p><strong>Les données personnelles</strong> sont toutes les informations relatives à une personne identifiée ou identifiable.</p>\r\n<p><strong>Service</strong> fait référence au site Web.</p>\r\n<p><strong>Prestataire de services</strong> désigne toute personne physique ou morale qui traite les données pour le compte de la Société. Il fait référence à des sociétés tierces ou à des personnes employées par la Société pour faciliter le Service, pour fournir le Service au nom de la Société, pour effectuer des services liés au Service ou pour aider la Société à analyser la manière dont le Service est utilisé.</p>\r\n<p><strong>Données d\'utilisation</strong> fait référence aux données collectées automatiquement, soit générées par l\'utilisation du Service, soit à partir de l\'infrastructure du Service elle-même (par exemple, la durée de la visite d\'une page).</p>\r\n<p><strong>Site Web</strong> fait référence à https: //ishop.cholobangla.com/, accessible depuis <a href=\"ishop.cholobangla\" rel=\"external nofollow noopener\" target=\"_blank\">ishop. cholobangla.com</a></p>\r\n<p><strong>Vous</strong> désigne la personne accédant ou utilisant le Service, ou la société ou toute autre entité pour le compte de laquelle cette personne accède ou utilise le Service, selon le cas.</p>\r\n<h1 style = \"margin: 30px 0;\">Collecte et utilisation de vos données personnelles</h1>\r\n<h2 style = \"margin: 30px 0;\">Types de données collectées</h2>\r\n<h3 style = \"margin: 30px 0;\">Données personnelles</h3>\r\n<p>Lorsque vous utilisez Notre Service, Nous pouvons Vous demander de Nous fournir certaines informations personnellement identifiables qui peuvent être utilisées pour Vous contacter ou Vous identifier. Les informations personnellement identifiables peuvent inclure, mais sans s\'y limiter: </p>\r\n<ul style = \"margin: 30px 0;\"><li>Adresse e-mail</li><li>Prénom et nom</li><li>Adresse, État, Province, Code postal/ZIP, Ville</ li><li>Données d\'utilisation</li></ul>\r\n<h3 style = \"margin: 30px 0;\">Données d\'utilisation</h3>\r\n<p>Les données d\'utilisation sont collectées automatiquement lors de l\'utilisation du service.</p><p>Les données d\'utilisation peuvent inclure des informations telles que l\'adresse de protocole Internet de votre appareil (par exemple, l\'adresse IP), le type de navigateur, la version du navigateur, les pages de notre service qui Votre visite, l\'heure et la date de votre visite, le temps passé sur ces pages, les identifiants uniques de l\'appareil et d\'autres données de diagnostic.</p><p>Lorsque vous accédez au Service par ou via un appareil mobile, nous pouvons collecter certaines informations automatiquement , y compris, mais sans s\'y limiter, le type d\'appareil mobile que vous utilisez, l\'identifiant unique de votre appareil mobile, l\'adresse IP de votre appareil mobile, votre système d\'exploitation mobile, le type de navigateur Internet mobile que vous utilisez, les identifiants uniques de l\'appareil et d\'autres diagnostics données.</p>\r\n<p>Nous pouvons également collecter des informations que votre navigateur envoie chaque fois que vous visitez notre service ou lorsque vous accédez au service par ou via un appareil mobile.</p>\r\n<h3 style = \"margin: 30px 0;\">Technologies de suivi et cookies</h3>\r\n<p>Nous utilisons des cookies et des technologies de suivi similaires pour suivre l\'activité sur notre service et stocker certaines informations. Les technologies de suivi utilisées sont des balises, des balises et des scripts pour collecter et suivre les informations et pour améliorer et analyser notre service. Les technologies que Nous utilisons peuvent inclure : </p>\r\n<p><strong>Cookies ou cookies de navigateur.</strong> Un cookie est un petit fichier placé sur votre appareil. Vous pouvez demander à Votre navigateur de refuser tous les Cookies ou de vous signaler l\'envoi d\'un Cookie. Cependant, si vous n\'acceptez pas les cookies, vous ne pourrez peut-être pas utiliser certaines parties de notre service. À moins que vous n\'ayez réglé les paramètres de votre navigateur pour qu\'il refuse les cookies, notre service peut utiliser des cookies. </p>\r\n<p><strong>Balises Web.</strong> Certaines sections de notre Service et nos e-mails peuvent contenir de petites\r\nfichiers électroniques connus sous le nom de balises Web (également appelés gifs clairs, pixels invisibles et gifs à pixel unique) qui permettent à la Société, par exemple, de compter les utilisateurs qui ont visité ces\r\npages ou ouvert un e-mail et pour d\'autres statistiques de site Web connexes (par exemple, enregistrer la popularité d\'une certaine section et vérifier l\'intégrité du système et du serveur).</p>\r\n<p>Les cookies peuvent être &quot;Persistants&quot; ou &quot;Session&quot; Biscuits. Les cookies persistants restent sur votre ordinateur personnel ou votre appareil mobile lorsque vous vous déconnectez, tandis que les cookies de session sont supprimés dès que vous fermez votre navigateur Web. Pour en savoir plus sur les cookies, consultez l\'article du <a href = \"https://www.freeprivacypolicy.com/blog/sample-privacy-policy-template/#Use_Of_Cookies_And_Tracking\" target=\"_blank\"> site Web sur la politique de confidentialité gratuite</a>. </p>\r\n<p>Nous utilisons à la fois des cookies de session et des cookies persistants aux fins décrites ci-dessous: </p>\r\n<p><strong>Cookies nécessaires/essentiels</strong></p>\r\n<p>Type: Cookies de session</p>\r\n<p>Géré par : Nous</p>\r\n<p>Objectif: Ces cookies sont essentiels pour vous fournir les services disponibles via le site Web et pour vous permettre d\'utiliser certaines de ses fonctionnalités. Ils aident à authentifier les utilisateurs et à empêcher l\'utilisation frauduleuse des comptes d\'utilisateurs. Sans ces cookies, les services que vous avez demandés ne peuvent pas être fournis, et nous n\'utilisons ces cookies que pour vous fournir ces services.</p>\r\n<p><strong>Politique relative aux cookies / Avis d\'acceptation des cookies</strong></p>\r\n<p>Type: Cookies persistants</p><p>Géré par: Nous</p><p>Objectif: Ces cookies identifient si les utilisateurs ont accepté l\'utilisation de cookies sur le site Web.</p><p>< strong>Cookies de fonctionnalité</strong></p><p>Type: Cookies persistants</p><p>Gérés par: Nous</p><p>Objectif: Ces cookies nous permettent de mémoriser les choix que vous faites lorsque vous utiliser le site Web, comme la mémorisation de vos informations de connexion ou de votre préférence de langue. Ces Cookies ont pour but de Vous offrir une expérience plus personnelle et de Vous éviter d\'avoir à ressaisir vos préférences à chaque fois que Vous utilisez le Site.</p><p>Pour plus d\'informations sur les cookies que nous utilisons et vos choix en matière de cookies , veuillez consulter notre politique relative aux cookies ou la section relative aux cookies de notre politique de confidentialité.</p>\r\n<h2 style = \"margin: 30px 0;\">Utilisation de vos données personnelles</h2><p>La Société peut utiliser les données personnelles aux fins suivantes:</p>\r\n<p><strong>Pour fournir et maintenir notre Service</strong>, y compris pour surveiller l\'utilisation de notre Service.</p>\r\n<p><strong>Pour gérer Votre Compte : </strong> pour gérer Votre inscription en tant qu\'utilisateur du Service. Les Données Personnelles que Vous fournissez peuvent Vous donner accès à différentes fonctionnalités du Service qui Vous sont accessibles en tant qu\'utilisateur inscrit.</p><p><strong>Pour l\'exécution d\'un contrat:</strong> le développement, le respect et l\'engagement du contrat d\'achat des produits, articles ou services que vous avez achetés ou de tout autre contrat avec nous par le biais du service.</p><p><strong>Pour vous contacter:</strong> Pour vous contacter par e-mail, appels téléphoniques , SMS ou autres formes équivalentes de communication électronique, telles que les notifications push d\'une application mobile concernant les mises à jour ou les communications informatives liées aux fonctionnalités, produits ou services sous contrat, y compris les mises à jour de sécurité, lorsque cela est nécessaire ou raisonnable pour leur mise en œuvre.</p><p>< strong>Pour vous fournir</strong> des actualités, des offres spéciales et des informations générales sur d\'autres biens, services et événements que nous proposons qui sont similaires à ceux que vous avez déjà achetés ou sur lesquels vous vous êtes renseigné, sauf si vous avez choisi de ne pas recevoir ces informations.</p><p><strong>Pour gérer vos demandes:</strong> Pour assister et gérer vos demandes.</p><p><strong>Pour les transferts d\'entreprise:</strong> Nous pouvons utiliser vos informations pour évaluer ou mener une fusion, une cession, une restructuration, une réorganisation, une dissolution ou toute autre vente ou transfert de tout ou partie de nos actifs, que ce soit dans le cadre d\'une entreprise en activité ou dans le cadre d\'une faillite, d\'une liquidation ou d\'une procédure similaire, dans laquelle les données personnelles que nous détenons sur nos Serviceusers fait partie des actifs transférés.</p>\r\n<p><strong>À d\'autres fins</strong>: nous pouvons utiliser vos informations à d\'autres fins, telles que l\'analyse des données, l\'identification des tendances d\'utilisation, la détermination de l\'efficacité de nos campagnes promotionnelles et pour évaluer et améliorer notre service, nos produits, nos services, notre marketing et votre expérience.</p>\r\n<p>Nous pouvons partager Vos informations personnelles dans les situations suivantes: </p>\r\n<ul style = \"margin: 30px 0;\"><li><strong>Avec les fournisseurs de services:</strong> nous pouvons partager vos informations personnelles avec les fournisseurs de services pour surveiller et analyser l\'utilisation de notre service, pour vous contacter.</ li><li><strong>Pour les transferts d\'entreprise:</strong> Nous pouvons partager ou transférer Vos informations personnelles dans le cadre de, ou pendant les négociations de, toute fusion, vente d\'actifs de la Société, financement ou acquisition de tout ou partie de Notre entreprise à une autre société.</li><li><strong>Avec des affiliés:</strong> nous pouvons partager vos informations avec nos affiliés, auquel cas nous exigerons de ces affiliés qu\'ils respectent cette politique de confidentialité. Les affiliés incluent notre société mère et toutes autres filiales, partenaires de coentreprise ou autres sociétés que nous contrôlons ou qui sont sous contrôle commun avec nous.</li><li><strong>Avec des partenaires commerciaux:</strong> nous pouvons partager vos informations avec Nos partenaires commerciaux pour vous offrir certains produits, services ou promotions.</li><li><strong>Avec d\'autres utilisateurs:</strong> lorsque vous partagez des informations personnelles ou interagissez autrement dans les espaces publics avec d\'autres utilisateurs, ces informations peuvent être consultées par tous les utilisateurs et peuvent être diffusées publiquement à l\'extérieur.</li><li><strong>Avec Votre consentement</strong>: Nous pouvons divulguer Vos informations personnelles à toute autre fin avec Votre consentement.</li></ul>\r\n<h2 style = \"margin: 30px 0;\">Conservation de vos données personnelles</h2>\r\n<p>La Société ne conservera vos données personnelles que le temps nécessaire aux fins énoncées\r\ndans cette politique de confidentialité. Nous conserverons et utiliserons vos données personnelles dans la mesure nécessaire pour nous conformer\r\nà nos obligations légales (par exemple, si nous sommes tenus de conserver vos données pour nous conformer à\r\nlois applicables), résoudre les litiges et appliquer nos accords et politiques juridiques.</p>\r\n<p>La Société conservera également les Données d\'utilisation à des fins d\'analyse interne. Les données d\'utilisation sont généralement conservées pendant une période plus courte, sauf lorsque ces données sont utilisées pour renforcer la sécurité ou pour améliorer la fonctionnalité de notre service, ou lorsque nous sommes légalement tenus de conserver ces données pendant des périodes plus longues.</p>\r\n<h2 style = \"margin: 30px 0;\">Transfert de vos données personnelles</h2>\r\n<p>Vos informations, y compris les données personnelles, sont traitées dans les bureaux d\'exploitation de la société et dans tout autre lieu où se trouvent les parties impliquées dans le traitement. Cela signifie que cela\r\nles informations peuvent être transférées et conservées sur des ordinateurs situés en dehors de votre état, province, pays ou autre juridiction gouvernementale où les lois sur la protection des données peuvent différer de celles de votre juridiction.</p>\r\n<p>Votre consentement à cette politique de confidentialité suivi de votre soumission de ces informations représente votre accord à ce transfert.</p>\r\n<p>La Société prendra toutes les mesures raisonnablement nécessaires pour s\'assurer que Vos données sont traitées en toute sécurité et conformément à la présente Politique de confidentialité et aucun transfert de Vos Données personnelles n\'aura lieu vers une organisation ou un pays à moins que des contrôles adéquats ne soient en place, y compris la sécurité de vos données et autres informations personnelles.</p>\r\n<h2 style = \"margin: 30px 0;\">Supprimer vos données personnelles</h2>\r\n<p>Vous avez le droit de supprimer ou de demander que nous vous aidions à supprimer les données personnelles que nous avons collectées à votre sujet.</p>\r\n<p>Notre service peut vous donner la possibilité de supprimer certaines informations vous concernant depuis le service.</p>\r\n<p>Vous pouvez mettre à jour, modifier ou supprimer vos informations à tout moment en vous connectant à votre compte, si vous en avez un, et en visitant la section des paramètres du compte qui vous permet de gérer vos informations personnelles. Vous pouvez également nous contacter pour demander l\'accès, la correction ou la suppression de toute information personnelle que vous nous avez fournie.</p>\r\n<p>Veuillez noter, cependant, que nous pouvons avoir besoin de conserver certaines informations lorsque nous avons une obligation légale ou une base légale pour le faire.</p>\r\n<h2 style = \"margin: 30px 0;\">Divulgation de vos données personnelles</h2>\r\n<h3 style = \"margin: 30px 0;\">Transactions commerciales</h3>\r\n<p>Si la Société est impliquée dans une fusion, une acquisition ou une vente d\'actifs, vos données personnelles peuvent être transférées. Nous vous informerons avant que vos données personnelles ne soient transférées et soumises à une politique de confidentialité différente.</p>\r\n<h3 style = \"margin: 30px 0;\">Application de la loi</h3>\r\n<p>Dans certaines circonstances, la Société peut être tenue de divulguer vos données personnelles si la loi l\'exige ou en réponse à des demandes valables d\'autorités publiques (par exemple, un tribunal ou une agence gouvernementale).</p>\r\n<h3 style = \"margin: 30px 0;\">Autres exigences légales</h3>\r\n<p>La Société peut divulguer Vos Données Personnelles en croyant de bonne foi qu\'une telle action est nécessaire pour: </p>\r\n<ul><li>Se conformer à une obligation légale</li><li>Protéger et défendre les droits ou la propriété de la Société</li><li>Prévenir ou enquêter sur d\'éventuels actes répréhensibles en rapport avec le Service</li>< li>Protéger la sécurité personnelle des Utilisateurs du Service ou du public</li><li>Protéger contre la responsabilité légale</li></ul>\r\n<h2>Sécurité de vos données personnelles</h2>\r\n<p>La sécurité de vos données personnelles est importante pour nous, mais n\'oubliez pas qu\'aucune méthode de transmission sur Internet ou méthode de stockage électronique n\'est sécurisée à 100%. Bien que nous nous efforcions d\'utiliser des moyens commercialement acceptables pour protéger vos données personnelles, nous ne pouvons garantir leur sécurité absolue.</p>\r\n<h1>Confidentialité des enfants</h1>\r\n<p>Notre Service ne s\'adresse pas aux personnes de moins de 13ans. Nous ne collectons pas sciemment d\'informations personnellement identifiables auprès de personnes de moins de 13ans. Si vous êtes un parent ou un tuteur et que vous savez que votre enfant nous a fourni des données personnelles , Contactez nous s\'il vous plait. Si nous apprenons que nous avons collecté des données personnelles auprès d\'une personne de moins de 13 ans sans vérification du consentement parental, nous prenons des mesures pour supprimer ces informations de nos serveurs.</p>\r\n<p>Si nous devons compter sur le consentement comme base légale pour le traitement de vos informations et que votre pays exige le consentement d\'un parent, nous pouvons exiger le consentement de votre parent avant de collecter et d\'utiliser ces informations.</p>\r\n<h1 style = \"margin: 30px 0;\">Liens vers d\'autres sites Web</h1>\r\n<p>Notre Service peut contenir des liens vers d\'autres sites Web qui ne sont pas exploités par Nous. Si vous cliquez sur un lien tiers, vous serez dirigé vers le site de ce tiers. Nous vous conseillons vivement de consulter la politique de confidentialité de chaque site que vous visitez.</p>\r\n<p>Nous n\'avons aucun contrôle sur et n\'assumons aucune responsabilité quant au contenu, aux politiques de confidentialité ou aux pratiques de tout site ou service tiers.</p>\r\n<h1 style = \"margin: 30px 0;\">Modifications de cette politique de confidentialité</h1>\r\n<p>Nous pouvons mettre à jour notre politique de confidentialité de temps à autre. Nous vous informerons de tout changement en publiant la nouvelle politique de confidentialité sur cette page.</p>\r\n<p>Nous vous informerons par e-mail et/ou par un avis visible sur notre service, avant que le changement ne devienne effectif et mettrons à jour la &quot;Dernière mise à jour&quot; date en haut de cette politique de confidentialité.</p>\r\n<p>Il vous est conseillé de consulter régulièrement cette politique de confidentialité pour tout changement. Les modifications apportées à cette politique de confidentialité entrent en vigueur lorsqu\'elles sont publiées sur cette page.</p>\r\n<h1 style = \"margin: 30px 0;\">Contactez-nous</h1>\r\n<p>Si vous avez des questions concernant cette politique de confidentialité, vous pouvez nous contacter: </p>\r\n<ul style = \"margin: 30px 0;\"><li>En visitant cette page sur notre site: <a href=\"https://ishop.cholobangla.com/\" rel=\"external nofollow noopener\" target=\"_blank \">https://ishop.cholobangla.com/</a></li></ul>\r\n<p>Généré à l\'aide de <a href = \"https://www.freeprivacypolicy.com/free-privacy-policy-generator/\"target=\"_blank\"> Générateur de politique de confidentialité gratuit</a></p>\r\n\r\n','Ishop - Aider','Aider','fr',6,'Aider');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (21,'2024-11-19 05:44:41','2024-11-21 17:35:15','Plan du site','Sitemap','Ishop - Plan du site','Plan du site','fr',7,'Plan,du,site');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (22,'2024-11-19 05:44:42','2024-11-21 17:35:15','के बारे में','<h1 style=\"margin: 30px 0;\">हमारे बारे में</h1>\r\n<h2 style=\"margin: 30px 0;\">परिभाषाएं</h2>\r\n<p><strong>खाता</strong> का अर्थ है कि हमारी सेवा या हमारी सेवा के कुछ हिस्सों तक पहुंचने के लिए आपके लिए बनाया गया एक अनूठा खाता।</p>\r\n<p><strong>कंपनी</strong> (इस अनुबंध में &quot;कंपनी&quot;, &quot;हम&quot;,&quot;हम&quot; या &quot;हमारा&quot; के रूप में संदर्भित) ishop.cholobangla.com, कनाडा को संदर्भित करता है। <</p>\r\n<p><strong>कुकीज़</strong> छोटी फ़ाइलें होती हैं जिन्हें किसी वेबसाइट द्वारा आपके कंप्यूटर, मोबाइल डिवाइस या किसी अन्य डिवाइस पर रखा जाता है, जिसमें उस वेबसाइट पर आपके ब्राउज़िंग इतिहास के कई उपयोगों के बीच उसका विवरण होता है।</p>\r\n<p><strong>देश</strong> संदर्भित करता है: न्यू ब्रंसविक, कनाडा</p>\r\n<p><strong>उपकरण</strong> का अर्थ है कोई भी उपकरण जो कंप्यूटर, सेलफोन या डिजिटल टैबलेट जैसी सेवा तक पहुंच सकता है।</p>\r\n<p><strong>व्यक्तिगत डेटा</strong> ऐसी कोई भी जानकारी है जो किसी पहचान योग्य व्यक्ति से संबंधित है।</p>\r\n<p><strong>सेवा</strong> वेबसाइट को संदर्भित करती है।</p>\r\n<p><strong>सेवा प्रदाता</strong> का अर्थ किसी प्राकृतिक या कानूनी व्यक्ति से है जो कंपनी की ओर से डेटा संसाधित करता है। यह तीसरे पक्ष की कंपनियों या कंपनी द्वारा नियोजित व्यक्तियों को सेवा की सुविधा के लिए संदर्भित करता है, कंपनी की ओर से सेवा प्रदान करने के लिए, सेवा से संबंधित सेवाओं का प्रदर्शन करने के लिए या सेवा का उपयोग कैसे किया जाता है, इसका विश्लेषण करने में कंपनी की सहायता करने के लिए।</p>\r\n<p><strong>उपयोग डेटा</strong> स्वचालित रूप से एकत्र किए गए डेटा को संदर्भित करता है, या तो सेवा के उपयोग से या स्वयं सेवा के बुनियादी ढांचे से उत्पन्न होता है (उदाहरण के लिए, पृष्ठ विज़िट की अवधि)।</p>\r\n<p><strong>वेबसाइट</strong> https://www.ishop.cholobangla.com/ को संदर्भित करता है, जिसे <a href=\"ishop.com\" rel=\"external nofollow noopener\" target=\"_blank\"> से एक्सेस किया जा सकता है ishop.cholobangla.com</a></p>\r\n<p><strong>आप</strong> का अर्थ उस व्यक्ति से है जो सेवा, या कंपनी, या अन्य कानूनी इकाई तक पहुंच बना रहा है या उसका उपयोग कर रहा है, जिसकी ओर से ऐसा व्यक्ति सेवा तक पहुंच बना रहा है या उपयोग कर रहा है, जैसा लागू हो।</p>\r\n','Ishop - के बारे में','के बारे में','hi',1,'के,बारे,में');
INSERT INTO `page_langs` (`id`, `created_at`, `updated_at`, `title`, `description`, `meta_title`, `meta_description`, `lang`, `page_id`, `meta_keywords`) VALUES (23,'2024-11-19 05:44:42','2024-11-21 17:35:15','सामान्य प्रश्न','<h1 style=\"margin: 30px 0;\">अक्सर पूछे जाने वाले प्रश्न</h1>\r\n<h2 style=\"margin: 30px 0;\">अवलोकन?</h2>\r\n<p>Ishop एक मल्टी वेंडर ईकॉमर्स CMS है। API <b>laravel</b>, एडमिन पैनल और फ्रंट एंड <strong>nuxt js</strong> के साथ बनाया गया है। डेटा <b>mysql स्टोर करने के लिए </b> का प्रयोग किया जा रहा है। अग्रिम <b>कैशिंग</b> प्रणाली के कारण साइट का प्रदर्शन बहुत तेज है। यह पूरी तरह उत्तरदायी और अत्यधिक अनुकूलन योग्य है। रेगुलर लाइसेंस एडमिन पैनल में बिल्ड फाइल्स नहीं मिलेंगी, इसका मतलब है कि आप एडमिन पैनल के किसी भी डिजाइन को कस्टमाइज नहीं कर पाएंगे। पैकेज फोल्डर में फ्रंटेंड और एपीआई सोर्स कोड मिलेगा। आप अपनी आवश्यकताओं के अनुसार दृश्यपटल और एपीआई को बहुत आसानी से अनुकूलित कर सकते हैं। विस्तारित लाइसेंस में एडमिन पैनल सोर्स कोड मिलेगा। किसी भी प्रश्न के लिए, कृपया हमारी टीम से <a href=\"mailto:iyozedcontact@gmail.com\" class=\"link\"><b>iyozedcontact@gmail.com</b></a></p> पर संपर्क करें।\r\n<h2 style=\"margin: 30px 0;\">क्या हम उपयोगकर्ताओं को इंस्टॉलेशन सहायता प्रदान करते हैं?</h2>\r\n<p>हां, हम उपयोगकर्ताओं को इंस्टॉलेशन सहायता प्रदान करते हैं। बेझिझक हमें कभी भी ईमेल करें।</p>\r\n<h2 style=\"margin: 30px 0;\">क्या हम उपयोगकर्ताओं को इंस्टॉलेशन गाइड प्रदान करते हैं?</h2>\r\n<p>हां, हम उपयोगकर्ताओं को पैकेज के साथ इंस्टॉलेशन गाइड प्रदान करते हैं।</p>\r\n<h2 style=\"margin: 30px 0;\">हमें उपयोगकर्ता के पास वापस जाने में कितना समय लगता है?</h2>\r\n<p>हम जितनी जल्दी हो सके उपयोगकर्ताओं को जवाब देते हैं।</p>\r\n','Ishop - सामान्य प्रश्न','सामान्य प्रश्न','hi',2,'सामान्य,प्रश्न');
