INSERT INTO `templates` (`id`, `title`, `content`, `type`, `created_at`, `updated_at`) VALUES (17,'Warranty','<p>Lorem ipsum dolor sit amet, consectetuer adipiscing elit. Aenean commodo ligula eget dolor. Aenean massa. Cum sociis natoque penatibus et magnis dis parturient montes, nascetur ridiculus mus. Donec quam felis, ultricies nec, pellentesque eu, pretium quis, sem. Nulla consequat massa quis enim. Donec pede justo, fringilla vel, aliquet nec, vulputate eget, arcu. In enim justo, rhoncus ut, imperdiet a, venenatis vitae, justo. Nullam dictum felis eu pede mollis pretium. Integer tincidunt. Cras dapibus. Vivamus elementum semper nisi. Aenean vulputate eleifend tellus. Aenean leo ligula, porttitor eu, consequat vitae, eleifend ac, enim. Aliquam lorem ante, dapibus in, viverra quis, feugiat a,</p>','system','2026-02-19 05:50:29','2026-02-19 05:50:29');
INSERT INTO `templates` (`id`, `title`, `content`, `type`, `created_at`, `updated_at`) VALUES (18,'Refund','<p>Lorem ipsum dolor sit amet, consectetuer adipiscing elit. Aenean commodo ligula eget dolor. Aenean massa. Cum sociis natoque penatibus et magnis dis parturient montes, nascetur ridiculus mus. Donec quam felis, ultricies nec, pellentesque eu, pretium quis, sem. Nulla consequat massa quis enim. Donec pede justo, fringilla vel, aliquet nec, vulputate eget, arcu. In enim justo, rhoncus ut, imperdiet a, venenatis vitae, justo. Nullam dictum felis eu pede mollis pretium. Integer tincidunt. Cras dapibus. Vivamus elementum semper nisi. Aenean vulputate eleifend tellus. Aenean leo ligula, porttitor eu, consequat vitae, eleifend ac, enim. Aliquam lorem ante, dapibus in, viverra quis, feugiat a,</p>','system','2026-02-19 05:50:39','2026-02-19 05:50:39');
INSERT INTO `templates` (`id`, `title`, `content`, `type`, `created_at`, `updated_at`) VALUES (19,'Delivery & Returns','<p>We aim to process and dispatch all orders as quickly as possible. Delivery times may vary depending on your location and product availability. Once your order has been shipped, you will receive a confirmation email with tracking details. Please ensure that all shipping information provided is accurate to avoid delays.</p><p><br></p><p>If you are not completely satisfied with your purchase, you may return eligible items within the specified return period in their original condition and packaging. Returned products must be unused and accompanied by proof of purchase. Refunds will be processed after the returned item has been inspected and approved. Shipping charges are non-refundable unless the return is due to a damaged, defective, or incorrect item.</p>','custom','2026-05-26 07:00:09','2026-05-26 07:00:09');
INSERT INTO `templates` (`id`, `title`, `content`, `type`, `created_at`, `updated_at`) VALUES (20,'Grading Process','<p>Each product undergoes a detailed grading and quality inspection process to ensure transparency and consistency. Devices are carefully tested for functionality, cosmetic condition, battery health, and overall performance before being assigned a grade. Grading categories are based on visible wear and condition, helping customers clearly understand the appearance and quality of the product before purchase.</p><p><br></p><p>All graded products are fully functional unless otherwise specified. Minor cosmetic imperfections such as light scratches or signs of previous use may vary depending on the assigned grade, but these do not affect the performance of the device. Our grading standards are designed to provide reliable and accurate product expectations for every customer.</p>','custom','2026-05-26 07:00:26','2026-05-26 07:00:26');
INSERT INTO `templates` (`id`, `title`, `content`, `type`, `created_at`, `updated_at`) VALUES (21,'Backorders','<p>Some products may be available on backorder when they are temporarily out of stock but expected to arrive soon. By placing a backorder, you reserve the item in advance, and your order will be processed and shipped once inventory becomes available. Estimated shipping timelines for backordered items may vary depending on supplier availability and restocking schedules.</p><p><br></p><p>Customers will be notified of any significant delays or updates related to their backordered items. If a product becomes unavailable or cannot be fulfilled within a reasonable timeframe, we will contact you with available options, including replacement, store credit, or refund. Payment for backordered products may be processed at the time the order is placed unless otherwise stated.</p>','custom','2026-05-26 07:00:39','2026-05-26 07:00:39');
